/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('modal','Modal comes from Late Latin modalis, “of a mode or measure,” based on modus (“measure, manner”); in grammar it concerns auxiliary verbs expressing possibility, necessity, or permission.',[C('modal.s1','语法概念','In the sentence “You should leave now,” should is a modal verb expressing advice rather than a completed action.','在“You should leave now”这句话中，should 是表示建议的情态动词，而不是已完成动作。','In the sentence “You should leave now” / should is a modal verb / expressing advice / rather than a completed action.','modal 作形容词修饰 verb，指表达可能、必要、许可等语气的助动词。','should 提供建议语气，所以是情态动词。'),C('modal.s2','统计众数','The analyst reported the modal income, the figure that appeared most often in the survey responses.','分析师报告了众数收入，即调查回答中出现次数最多的那个数值。','The analyst reported the modal income / the figure that appeared most often / in the survey responses.','统计学 modal 与 mode（众数）相关，表示出现频率最高的值。','例句直接把 modal income 解释为最常见的调查数值。')],M('In “You should leave,” should is a modal noun meaning the most frequent income value.','In “You should leave,” should is a modal verb expressing advice.','句中 should 是助动词；最常见数值的统计义不适用于该句。','confusable'),[q('What does should express in the quoted sentence?','advice','a past event','the most common income value','should 是表示建议的情态动词。',1),q('What is a modal income in statistics?','the value occurring most often','the average of all values','the highest value only','众数是出现次数最多的值。',2),q('Which word is a modal verb?','might','table','quickly','might 可表达可能性，属于情态动词。',1,'grammar'),q('Modal is based on a Latin word meaning?','measure or manner','water or sea','small or narrow','modus 的意义包括 measure 和 manner。',1,'word-formation')]);
P('mode','Mode came through French mode from Latin modus (“measure, manner”); it can mean a way of doing something, a prevailing style, or the most frequent value in statistics.',[C('mode.s1','操作方式','Select silent mode before the lecture begins so incoming calls do not interrupt the speaker.','讲座开始前选择静音模式，来电就不会打断演讲者。','Select silent mode / before the lecture begins / so incoming calls / do not interrupt the speaker.','mode 作名词指设备运行或做事的方式，常见搭配 include silent mode。','此处是手机运行状态的选择。'),C('mode.s2','流行风格','The designer revived a mode of dress from the 1960s, adapting its clean lines for modern fabrics.','设计师复兴了二十世纪六十年代的一种服装风格，并用现代面料改造简洁线条。','The designer revived a mode of dress from the 1960s / adapting its clean lines / for modern fabrics.','mode 也可指某时期流行的风格或样式。','服装样式与时代风格相联系。'),C('mode.s3','统计众数','The mode of the responses was “often,” which more participants selected than any other answer.','回答的众数是“经常”，选择它的人数多于任何其他选项。','The mode of the responses was “often” / which more participants selected / than any other answer.','统计学中 mode 指一组数据里出现最多的值。','“经常”选项被选择次数最多。')],M('The mode of the survey was the mean because it was selected more often than every other answer.','The mode of the survey was “often,” the answer selected most frequently.','被选次数最多的是众数；mean 是算术平均数。','confusable'),[q('Which setting prevents calls from interrupting the lecture?','silent mode','airplane model','the mean response','silent mode 是设备静音运行方式。',1),q('What did the designer revive?','a 1960s style of dress','a mathematical average','a phone notification','mode 可指某时代的流行风格。',2),q('Which response is the statistical mode?','the one selected most often','the one exactly in the middle after sorting','the sum divided by the number of replies','mode 是出现频率最高的值。',3,'confusable'),q('Select a mode before the lecture uses mode to mean?','a device setting or way of operating','a fashion designer','a spoken sentence','silent mode 是设备运行设置。',1,'meaning')]);
P('model','Model came through French modèle from Italian modello, ultimately from Latin modulus (“small measure”); it names a representation or example, a fashion model, a product type, or the verb to represent or display.',[C('model.s1','工程原型','The engineers tested a scale model of the bridge in a water tank before approving the full-size design.','工程师在批准全尺寸设计前，先把桥梁缩尺模型放进水槽测试。','The engineers tested a scale model of the bridge / in a water tank / before approving / the full-size design.','model 作名词可指供研究、展示或测试的模型。','缩尺桥梁被用来模拟真实结构。'),C('model.s2','行为典范','Her calm response to the emergency became a model for how the team should communicate under pressure.','她面对紧急情况时的冷静回应，成了团队在压力下沟通的范例。','Her calm response to the emergency / became a model / for how the team should communicate / under pressure.','model 可指值得效仿的榜样或典型。','团队把她的做法当作行为范例。'),C('model.s3','职业模特','The model wore the designer’s winter collection during the runway show.','模特在时装秀上展示了设计师的冬季系列。','The model wore the designer’s winter collection / during the runway show.','model 作名词也指展示服装或产品的人。','她穿着服装系列参加走秀，符合职业义。'),C('model.s4','产品型号','This model of the camera includes weather sealing that the cheaper version lacks.','这款相机型号配有较便宜版本没有的防风雨密封功能。','This model of the camera includes weather sealing / that the cheaper version lacks.','model 可指某一类产品的型号或版本。','句子比较同一相机产品的两个型号。'),C('model.s5','动词示范','The instructor modelled the safe lifting technique slowly before asking each worker to practise it.','讲师先慢慢示范安全搬抬技巧，然后让每位工人练习。','The instructor modelled the safe lifting technique slowly / before asking each worker / to practise it.','model 作及物动词可表示展示、示范，英式过去式常写 modelled。','讲师先做出动作供学员模仿。')],M('The instructor modelled safe lifting by telling workers to bend their backs and twist while carrying a load.','The instructor modelled safe lifting by bending at the knees and keeping the load close.','弯背并扭身搬重物并非安全示范。','meaning'),[q('What did the engineers test in the water tank?','a scale representation of the bridge','the finished full-size bridge','a fashion collection','scale model 是桥梁的缩尺模型。',1),q('How did her emergency response serve the team?','it became an example to follow','it identified a camera version','it displayed a winter collection','model 在此表示可效仿的范例。',2),q('Who wore the winter collection on the runway?','a fashion model','a bridge engineer','a camera technician','model 的职业义是展示服装的人。',3),q('In modelled the technique, model means?','demonstrate it for others','buy a camera version','measure a water tank','动词 model 可表示示范做法。',5,'grammar')]);
P('modeling','Modeling is model plus -ing and names constructing or shaping a representation; it also refers to working as a fashion model.',[C('modeling.s1','数据建模','The team’s climate modeling compared rainfall under three emissions scenarios before it advised the city on drainage.','团队的气候建模先比较三种排放情景下的降雨，再向市政府提出排水建议。','The team’s climate modeling compared rainfall / under three emissions scenarios / before it advised the city / on drainage.','modeling 作不可数名词可指用模型模拟或分析某个系统的过程。','团队用多个排放情景推演降雨。'),C('modeling.s2','模特工作','Modeling gave Aisha flexible hours, but she still had to travel to castings and maintain a portfolio.','模特工作给艾莎带来灵活工时，但她仍须参加试镜并维护作品集。','Modeling gave Aisha flexible hours / but she still had to travel to castings / and maintain a portfolio.','modeling 也可指从事时装或商业模特工作的职业活动。','试镜和作品集是模特行业的具体工作。')],M('The climate modeling team made no representation or simulation and simply guessed the rainfall figures.','The team used computer models to compare possible rainfall under several emissions scenarios.','没有建立或运行任何模型就不能称为 modeling。'),[q('What did the climate modeling compare?','rainfall under three emissions scenarios','three fashion portfolios','past rainfall only with no scenarios','建模比较不同排放情景的降雨。',1),q('What did Aisha travel to attend?','castings','climate conferences only','camera repair sessions','casting 是模特求职试镜。',2),q('Modeling in climate modeling refers to?','simulating a system with a representation','walking a runway','selling a camera','modeling 可指计算机模拟过程。',1,'context'),q('Which activity belongs to modeling as a career?','maintaining a portfolio for castings','calculating a bridge’s scale only','writing a drainage permit','维护作品集并参加试镜属于模特工作。',2,'context')]);
P('modem','Modem is a blend of modulator and demodulator, naming equipment that converts digital data to and from signals suitable for communication lines.',C('modem.s1','网络设备','The technician replaced the faulty modem, and the office computers reconnected to the internet within minutes.','技术员更换了故障调制解调器，办公室电脑几分钟内就重新连上互联网。','The technician replaced the faulty modem / and the office computers / reconnected to the internet / within minutes.','modem 作名词指调制解调器，负责在数字设备与通信信号之间转换数据。','更换设备后网络恢复连接。'),M('The technician replaced the modem with a loudspeaker that only amplified sound and could not transmit data.','The technician replaced the modem with a working device that could transmit and receive network data.','只放大声音的扬声器不具备调制解调器的数据转换功能。'),[q('What happened after the modem was replaced?','the office computers reconnected','the bridge model sank','the phone entered silent mode','更换 modem 后办公室网络恢复。'),q('What does a modem convert for communication?','digital data and line signals','paper documents into clothing','rainfall into drainage','modem 在数字数据与通信信号间转换。'),q('Modem blends which two words?','modulator and demodulator','modern and model','mode and medium','modem 是 modulator 与 demodulator 的混成词。',1,'word-formation'),q('Which device belongs in a network setup?','a modem','a sugar mould','a molar tooth','调制解调器是网络通信设备。')]);
P('moderate','Moderate comes from Latin moderatus, the past participle of moderari (“control, regulate”); it describes an amount that is not extreme, a politically middle position, or the verbs to chair or make less intense.',[C('moderate.s1','强度适中','The forecast calls for moderate rain, enough to wet the garden but not enough to flood the road.','天气预报称将有中雨，足以淋湿花园，但不足以淹没道路。','The forecast calls for moderate rain / enough to wet the garden / but not enough / to flood the road.','moderate 作形容词表示程度适中、不极端。','雨量介于小雨与暴雨之间。'),C('moderate.s2','政治立场','The candidate took a moderate position on tax, supporting gradual changes instead of an abrupt overhaul.','候选人在税收问题上持温和立场，支持逐步调整而非突然全面改革。','The candidate took a moderate position on tax / supporting gradual changes / instead of an abrupt overhaul.','政治语境的 moderate 指温和、不激进的立场。','渐进改革与激进大幅变动相对。'),C('moderate.s3','调节缓和','A short walk helped moderate the team’s frustration after the delayed launch.','发布延期后，散步一会儿帮助团队缓和了挫败感。','A short walk helped moderate the team’s frustration / after the delayed launch.','moderate 作及物动词可表示降低、缓和程度。','散步使挫败感减轻。'),C('moderate.s4','主持讨论','Dr Chen will moderate the panel discussion and give each speaker equal time for questions.','陈博士将主持小组讨论，并给每位发言者同等的提问时间。','Dr Chen will moderate the panel discussion / and give each speaker / equal time for questions.','moderate 作动词还可指主持讨论或论坛。','控制发言顺序和时间体现主持作用。'),C('moderate.s5','温和派成员','A moderate in the party urged both factions to agree on a practical compromise.','党内一位温和派成员敦促两个派别达成务实妥协。','A moderate in the party urged both factions / to agree on a practical compromise.','moderate 作名词可指政治或意见上的温和派人士。','他推动妥协，符合温和派义。')],M('The forecast described the rain as moderate even though it was a record-breaking flood that swept away bridges.','The forecast described steady, non-extreme rain as moderate.','毁桥洪水属于极端降雨，不能称为程度适中的雨。'),[q('How heavy was the forecast rain?','enough to wet the garden but not flood roads','a record flood','no rain at all','moderate 表示不极端的中等程度。',1),q('What position did the candidate take on tax?','gradual change rather than an abrupt overhaul','immediate abolition of all taxes','no position was stated','政治上 moderate 指温和、不激进。',2),q('What did the walk do to frustration?','reduced or softened it','made it more intense','turned it into rainfall','moderate 作动词可表示缓和情绪。',3),q('What will Dr Chen do at the panel?','chair the discussion and manage speaking time','vote as a candidate','measure rain intensity','主持论坛是 moderate 的动词义。',4,'collocation')]);
P('moderately','Moderately is moderate plus -ly and means to a middle degree, without being excessive.',C('moderately.s1','程度描述','The refurbished flat is moderately priced, making it affordable for young workers without being the cheapest option in town.','翻修后的公寓价格适中，年轻职工负担得起，但并非全镇最便宜的选择。','The refurbished flat is moderately priced / making it affordable for young workers / without being the cheapest option in town.','moderately 修饰 priced，表示价格程度适中而非极端高低。','价格可负担但不是最低价，正体现中等程度。'),M('The flat was moderately priced at ten times the local market rate.','The flat was moderately priced near the local average.','远高于当地行情的价格不能称为适中。','word-choice'),[q('How was the flat priced?','at a middle, affordable level','at the highest price in town','for free','moderately 表示程度适中。'),q('Was it the cheapest option?','no, it was affordable but not the cheapest','yes, it was free','no, it cost ten times the market rate','例句特意说明它并非最便宜。'),q('In moderately priced, moderately modifies?','the adjective priced','the noun flat','the verb refurbished','副词 moderately 描述价格水平。',1,'grammar'),q('Which meal is moderately spicy?','noticeably seasoned but not very hot','so hot it is painful','completely unseasoned and cold','moderately 表示不极端的程度。',1,'context')]);
P('moderation','Moderation comes from Latin moderatio (“control, regulation”), from moderari; it means avoiding excess or making a force, tone, or conflict less intense.',[C('moderation.s1','适量原则','The doctor advised moderation with sugary drinks, suggesting one small serving rather than several cans each day.','医生建议适量饮用含糖饮料，每天一小份而不是好几罐。','The doctor advised moderation with sugary drinks / suggesting one small serving / rather than several cans each day.','moderation 作名词指适度、不过量，常见搭配是 in moderation。','建议限量饮用体现避免过度。'),C('moderation.s2','冲突缓和','The mediator’s moderation of the heated discussion helped both sides return to the original question.','调解员对激烈讨论的缓和，帮助双方回到最初的问题上。','The mediator’s moderation of the heated discussion / helped both sides / return to the original question.','moderation 也可指使语气或冲突缓和的过程。','调解后双方不再争吵并回到议题。')],M('The nutritionist recommended moderation by drinking several sugary cans at every meal.','The nutritionist recommended moderation by limiting sugary drinks to an occasional small serving.','大量频繁饮用与适量原则相反。'),[q('How many sugary drinks did the doctor recommend?','one small serving rather than several cans','several cans every day','none of the patient’s meals','建议限制分量体现 moderation。',1),q('What did the mediator’s moderation achieve?','it helped the sides return to the issue','it made the argument more heated','it selected a new candidate','缓和讨论后双方回到议题。',2),q('Which phrase means consuming without excess?','eat sweets in moderation','eat sweets to moderation of','moderation the sweets','常见结构是 in moderation。',1,'collocation'),q('Moderation is related to the verb?','moderate','model','modernise','moderation 与 moderate 同源，含控制、调节义。',1,'word-formation')]);
P('modern','Modern came through French moderne from Latin modernus, based on modo (“just now”); it means belonging to the present or recent times, or having a current style.',[C('modern.s1','当代科技','The museum’s modern wing uses interactive screens to explain how current solar panels convert sunlight into electricity.','博物馆的现代展厅用互动屏幕说明当代太阳能板如何把阳光转化为电能。','The museum’s modern wing uses interactive screens / to explain how current solar panels / convert sunlight / into electricity.','modern 可指当前或近代的事物，具体时间范围依语境而定。','展厅展示当代太阳能技术。'),C('modern.s2','新式设计','Although the cottage is old, its modern kitchen has flat-front cabinets and energy-efficient appliances.','这座小屋虽然年代久远，但现代化厨房配有平板柜门和节能电器。','Although the cottage is old / its modern kitchen has flat-front cabinets / and energy-efficient appliances.','modern 也可描述新式、时尚或采用当前设计的样式。','旧房内的新式厨房符合设计义。')],M('The guide called a newly invented solar panel medieval because it uses current technology.','The guide called the newly invented solar panel modern because it uses current technology.','采用当前技术的设备是 modern，不是 medieval。'),[q('What does the modern wing explain?','how current solar panels work','how medieval mills ground wheat','how a monarchy chooses a ruler','展厅介绍当前太阳能技术。',1),q('What makes the kitchen modern?','its current cabinet design and efficient appliances','the cottage’s age alone','its lack of electricity','新式设计和节能电器体现 modern。',2),q('Which is a modern device?','a current-generation tablet','a Roman clay tablet','a stone road marker','当前一代设备符合 modern 的时代义。',1,'context'),q('Modern derives from Latin modo, meaning?','just now','far away','one thousand','modo 指“刚刚、现在”。',1,'word-formation')]);
P('modernisation','Modernisation is the British -isation form of modernize plus -ation; it names the process of making an institution, system, or place more current.',C('modernisation.s1','公共设施更新','The hospital’s modernisation added digital records and new lifts while keeping the historic entrance intact.','医院现代化改造增加了电子病历和新电梯，同时保留了历史入口。','The hospital’s modernisation added digital records and new lifts / while keeping / the historic entrance intact.','modernisation 作名词指更新设施、技术或制度的过程；modernization 是美式常见拼法。','新技术升级且保留旧入口，体现现代化改造。'),M('The hospital called removing its digital records and disabling new lifts modernisation.','The hospital called installing digital records and new lifts modernisation.','撤掉新设备不是使机构更现代的改造。'),[q('What did the hospital’s modernisation add?','digital records and new lifts','paper-only charts and broken lifts','a new monastery','现代化引入电子记录和新电梯。'),q('What historic feature was kept?','the entrance','the old filing system','the broken lift','项目保留了历史入口。'),q('Modernisation names?','the process of updating a system','a person who models clothes','a single current appliance','-isation 形成表示过程的名词。',1,'word-formation'),q('Which spelling is common in British English?','modernisation','modernizasion','modornisation','British English commonly uses -isation for this noun.',1,'spelling')]);
P('modernism','Modernism combines modern with -ism and names movements that deliberately broke with earlier artistic or literary conventions.',C('modernism.s1','艺术史','The gallery’s modernism exhibit placed abstract canvases beside early twentieth-century furniture and design notes.','画廊的现代主义展览把抽象画布与二十世纪初的家具和设计笔记并列展出。','The gallery’s modernism exhibit placed abstract canvases / beside early twentieth-century furniture / and design notes.','modernism 作名词指现代主义艺术、文学或设计运动。','抽象作品与早期现代设计被作为运动的例子展出。'),M('The curator labelled the exhibit modernism although every work copied medieval styles and rejected experimentation.','The curator labelled the exhibit modernism because it showed works breaking from older conventions.','完全沿袭旧风格且拒绝创新，与现代主义的特征相反。'),[q('What appeared in the modernism exhibit?','abstract canvases and early modern design','only medieval manuscripts','a collection of tax records','展览呈现抽象作品及现代设计。'),q('Modernism often reacted against?','older artistic conventions','all new technology','mathematical averages','现代主义常打破先前的艺术惯例。'),q('Which work might belong to modernism?','an experimental abstract painting','a faithful copy of a medieval tapestry only','a list of building measurements','实验性抽象艺术符合现代主义取向。',1,'context'),q('The suffix -ism commonly forms a noun for?','a movement or system of ideas','a person who performs one action','the past tense','modernism 是一种艺术运动名称。',1,'word-formation')]);
P('modernist','Modernist combines modern with -ist and names a person associated with modernism or a work reflecting its experimental approach.',C('modernist.s1','文学风格','The modernist poet broke the regular rhyme scheme and shifted between several speakers in one short poem.','这位现代主义诗人打破规则押韵，并在一首短诗中切换多个说话者。','The modernist poet broke the regular rhyme scheme / and shifted between several speakers / in one short poem.','modernist 作名词指现代主义运动中的人物，也可作形容词修饰艺术作品。','实验形式体现诗人的现代主义风格。'),M('The critic called the poet a modernist because the poet refused every experiment and copied a fixed traditional form.','The critic called the poet a modernist because the poet experimented with form and voice.','完全拒绝实验并机械复制传统格式，不能支撑此处的 modernist 判断。'),[q('What did the poet change?','the rhyme scheme and speaker pattern','the poem’s paper size only','the date of publication','现代主义诗人打破格律并改变叙述声音。'),q('What does modernist name here?','a poet associated with modernism','a statistical mode','a solar panel','modernist 可指现代主义创作者。'),q('Which book might be called modernist?','one experimenting with narrative structure','one that only copies a medieval prayer','a manual for modem repair','形式实验符合现代主义。',1,'context'),q('Modernist is formed from modern plus?','-ist','-ize','-ity','-ist 可表示与运动相关的人。',1,'word-formation')]);
P('modernistic','Modernistic is modernist plus -ic, an adjective describing a modernist or conspicuously modern style.',C('modernistic.s1','建筑风格','The station’s modernistic canopy used clean geometric lines that contrasted with the brickwork of the nineteenth-century hall.','车站现代主义风格的雨棚采用简洁几何线条，与十九世纪大厅的砖墙形成对比。','The station’s modernistic canopy used clean geometric lines / that contrasted with the brickwork / of the nineteenth-century hall.','modernistic 作形容词修饰 canopy，强调显著的新式或现代主义设计。','几何线条与旧砖墙形成明确的风格对比。'),M('The architect described the plain medieval stone arch as modernistic despite its unchanged centuries-old design.','The architect described the new geometric canopy as modernistic.','未改变的中世纪拱门并非新式现代主义设计。'),[q('What feature looked modernistic?','the canopy with geometric lines','the old brickwork','the nineteenth-century hall’s age','现代主义风格体现在新雨棚的几何线条。'),q('What did the canopy contrast with?','the historic brickwork','the station ticket price','a fashion model','新式雨棚与旧砖墙形成对比。'),q('Modernistic is used as?','an adjective describing a style','a noun for a statistical value','a verb meaning to moderate','modernistic 修饰 canopy，是形容词。',1,'grammar'),q('Which design seems modernistic?','a new structure with bold geometric forms','an unchanged medieval arch','a handwritten receipt','几何造型的新结构符合现代主义风格。',1,'context')]);
P('modernity','Modernity comes from modern plus -ity and means the state or distinctive qualities of being modern.',C('modernity.s1','社会变化','The historian linked urban modernity to electric lighting, mass transit, and changing patterns of work.','历史学家把城市现代性与电灯、公共交通和工作方式的变化联系起来。','The historian linked urban modernity / to electric lighting, mass transit, / and changing patterns of work.','modernity 作抽象名词，指现代社会的状态及其特征。','电力、交通与工作模式展现现代社会特征。'),M('The historian defined modernity as a society with no technology, transport, or changes in work.','The historian associated modernity with new infrastructure and changing social patterns.','没有技术与社会变化不能体现现代社会状态。'),[q('Which developments were linked to urban modernity?','electric lighting and mass transit','a stone bridge and horse-only travel','an ancient monastery alone','新基础设施被视作城市现代性的表现。'),q('Modernity means?','the condition or qualities of being modern','a device that converts data signals','a single fashion model','modernity 是现代状态及特征。'),q('Which change may signal modernity?','the spread of electric public transport','the removal of all city lighting','a return to walking everywhere by rule','公共电力交通可体现社会现代化。',1,'context'),q('The suffix -ity turns modern into?','an abstract noun','a past-tense verb','a plural adjective','modernity 是抽象名词。',1,'word-formation')]);
P('modernization','Modernization is modernize plus -ation, the process of updating equipment, services, or institutions; modernization is the usual US spelling of modernisation.',C('modernization.s1','工业升级','The factory’s modernization replaced diesel pumps with efficient electric motors and trained staff to maintain them.','工厂现代化改造用高效电动机替换柴油泵，并培训员工维护设备。','The factory’s modernization replaced diesel pumps / with efficient electric motors / and trained staff / to maintain them.','modernization 作名词指升级技术、设施或组织的过程。','更换设备并培训维护人员构成工厂升级。'),M('The factory’s modernization removed electric motors and returned the production line to older diesel pumps.','The factory’s modernization installed electric motors and updated maintenance training.','退回旧泵与现代化升级方向相反。'),[q('What replaced the diesel pumps?','efficient electric motors','a monastery water wheel','fashion runway lights','工厂用高效电动机替代旧柴油泵。'),q('What else changed during modernization?','staff received maintenance training','the factory stopped all production permanently','the motors were removed','员工培训也是设备升级的一部分。'),q('Modernization names?','the process of making systems more current','the abstract quality of being modest','one individual’s fashion career','modernization 表示现代化过程。',1,'meaning'),q('Which spelling is the usual US form?','modernization','modernisazion','modernizasion','US English commonly spells the noun with -ization.',1,'spelling')]);
P('modernize','Modernize combines modern and -ize, meaning to make a system, building, or service more suitable for current needs.',C('modernize.s1','设施更新','The town will modernize its water network by replacing leaking pipes and adding remote pressure sensors.','镇里将通过更换漏水管道并安装远程压力传感器来更新供水网络。','The town will modernize its water network / by replacing leaking pipes / and adding remote pressure sensors.','modernize 作及物动词，后接需要更新的系统或设施。','更换旧管道并加传感器使供水网络适应当前需要。'),M('The town plans to modernize the network by removing its working pipes and restoring the oldest leaks.','The town plans to modernize the network by replacing leaking pipes and adding monitoring sensors.','恢复漏水而不是修复会让设施更陈旧、不可靠。'),[q('What will the town modernize?','its water network','the railway’s medieval stone marker','the town’s Monday calendar','供水网络是更新对象。'),q('How will the network be upgraded?','by replacing leaks and adding sensors','by removing working pipes','by disabling pressure readings','修漏水并监测压力能提升系统。'),q('Which action modernizes a library?','adding searchable digital records','removing electricity and catalogues','making every book inaccessible','数字化目录能让服务适应当代需求。',1,'context'),q('Modernize is formed from modern plus?','-ize','-ist','-ism','-ize 构成表示“使变得现代”的动词。',1,'word-formation')]);
P('modest','Modest comes from Latin modestus, related to modus (“measure”); it describes a humble person, a limited amount, or clothing considered not revealing.',[C('modest.s1','谦逊态度','When colleagues praised her design, Mei gave a modest smile and credited the whole engineering team.','同事称赞她的设计时，梅谦逊地笑了笑，并把功劳归于整个工程团队。','When colleagues praised her design / Mei gave a modest smile / and credited the whole engineering team.','modest 作形容词可形容不自夸、谦逊的人或举止。','她不独揽功劳，体现谦逊。'),C('modest.s2','数量有限','The charity raised a modest sum at the village fair, enough to buy books for one classroom.','慈善机构在乡村集市上筹到一笔不多的款项，刚好够为一间教室买书。','The charity raised a modest sum / at the village fair / enough to buy books / for one classroom.','modest 可表示规模、数量或金额不大但仍有用。','款项不多，但足够资助一间教室。'),C('modest.s3','衣着端庄','The school asked visitors to wear modest clothing that covered shoulders and knees during the ceremony.','学校要求来访者在仪式期间穿着遮住肩部和膝盖的端庄服装。','The school asked visitors to wear modest clothing / that covered shoulders and knees / during the ceremony.','modest 修饰 clothing 时可表示不暴露、端庄得体。','着装标准明确要求遮盖肩膝。')],M('Mei was modest because she claimed sole credit for the design and dismissed the team’s work.','Mei was modest because she shared the credit with the engineering team.','独占功劳并贬低同事与谦逊相反。'),[q('How did Mei respond to praise?','she credited the whole team','she claimed she worked alone','she cancelled the design','她把功劳分给团队，体现谦逊。',1),q('Was the charity’s sum large?','no, it was limited but enough for one classroom','yes, it funded every school in the country','no, it was zero','modest sum 表示金额不大。',2),q('What did modest clothing cover?','shoulders and knees','only the hands','the face and shoes only','例句给出肩部和膝盖的着装要求。',3,'context'),q('Which person is modest?','one who accepts praise without boasting','one who takes all credit','one who exaggerates every achievement','modest 可形容谦逊、不自夸。',1,'meaning')]);
P('modestly','Modestly is modest plus -ly and means in a humble way or to a limited degree.',C('modestly.s1','谦虚回应','Asked about the award, the scientist spoke modestly and thanked the laboratory staff who had supported the research.','被问及奖项时，这位科学家谦逊地发言，并感谢支持研究的实验室员工。','Asked about the award / the scientist spoke modestly / and thanked the laboratory staff / who had supported the research.','modestly 修饰 spoke，描述谦逊的说话方式。','科学家将功劳归于同事，表现谦逊。'),M('The scientist spoke modestly by boasting that no colleague had contributed anything.','The scientist spoke modestly by acknowledging the laboratory team’s contribution.','否认同事贡献并自夸不是谦逊地发言。'),[q('How did the scientist speak?','in a humble way','in a boastful way','without answering at all','modestly 表示谦逊地。'),q('Whom did the scientist thank?','the laboratory staff','the award committee only','no one','科学家感谢了支持研究的实验室员工。'),q('In spoke modestly, modestly modifies?','the verb spoke','the noun scientist','the award','副词 modestly 修饰动词 spoke。',1,'grammar'),q('Which claim is expressed modestly?','I was fortunate to have a helpful team.','I alone did everything perfectly.','Everyone else was useless.','承认团队帮助而不自夸，体现 modestly。',1,'context')]);
P('modicum','Modicum comes from Latin modicum, “a moderate amount,” based on modus (“measure”); in English it usually means a small quantity, often of something abstract.',C('modicum.s1','少量耐心','The repair required a modicum of patience because each tiny screw had to be aligned before the panel would close.','这次维修需要一点耐心，因为必须先对准每颗小螺丝，面板才能合上。','The repair required a modicum of patience / because each tiny screw / had to be aligned / before the panel would close.','a modicum of + 不可数名词表示少量，常接 patience、evidence 等抽象名词。','维修只需一点耐心，但精细步骤不可省略。'),M('The repair required a modicum of patience, meaning an unlimited and overwhelming supply of patience.','The repair required a small amount of patience for the precise work.','modicum 表示少量，不表示无限或巨量。'),[q('What did the repair require?','a small amount of patience','an unlimited supply of screws','a large amount of rain','a modicum of patience 表示一点耐心。'),q('Why was patience needed?','the tiny screws had to be aligned','the panel was already closed','the repair involved no small parts','细小螺丝需精确对齐。'),q('Which phrase uses modicum naturally?','a modicum of evidence','a modicum of three metres','modicum the repair','modicum 常用 a modicum of + 抽象名词。',1,'collocation'),q('Modicum originally referred to?','a measured or moderate amount','a modernist painting','a device for internet signals','Latin modicum 表示适量、一定数量。',1,'word-formation')]);
P('modification','Modification comes from Latin modificatio, from modificare (“to measure or limit”); it names an alteration that adjusts something without necessarily replacing it.',C('modification.s1','设计调整','The only modification to the prototype was a wider handle, which made it easier for older users to grip.','原型唯一的改动是加宽手柄，这让年长用户更容易握住。','The only modification to the prototype was a wider handle / which made it easier / for older users / to grip.','modification 作名词指对原有物件或计划所作的调整。','只改宽手柄，其他原型内容保留。'),M('The report called the prototype modification even though no feature or detail had been changed.','The report listed the wider handle as a modification to the prototype.','没有任何改动就不能说发生了 modification。'),[q('What was changed on the prototype?','the handle was made wider','the entire product was replaced','the older users were removed','手柄加宽是唯一改动。'),q('Why make the handle wider?','to make gripping easier for older users','to change the product’s colour','to reduce the number of prototypes','加宽手柄改善握持。'),q('Modification is closest to?','an adjustment or alteration','a complete refusal','a person who models clothing','modification 指更改或调整。'),q('Which is a modification to a schedule?','moving one meeting by thirty minutes','cancelling every project and making no new plan','printing the unchanged schedule again','调整一场会议时间属于 modification。',1,'context')]);

(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('modify','Modify came from Latin modificare, “to measure or limit,” from modus (“measure”) plus facere (“make”); it means to change something partly.',C('modify.s1','计划调整','The council modified the bus route to serve the new clinic while keeping the original stops in the town centre.','市议会调整了公交线路以服务新诊所，同时保留镇中心原有站点。','The council modified the bus route / to serve the new clinic / while keeping the original stops / in the town centre.','modify 作及物动词，后接被改变的计划、物件或行为。','路线有所调整，但原有站点仍保留。'),M('The council modified the route by leaving every stop unchanged and making no alteration.','The council modified the route by adding a stop near the clinic.','没有任何变化就不能称为 modify。'),[q('Why did the council modify the route?','to serve the new clinic','to remove the town centre','to close the clinic','新增服务范围促使路线调整。'),q('What did the council keep?','the original town-centre stops','the old route without changes','the clinic’s timetable','虽然路线调整，镇中心站点仍保留。'),q('Modify most nearly means?','change partly','copy exactly','measure without changing','modify 表示对原物作部分改变。'),q('Which object can be modified?','a draft policy','a person into a mineral','a storm into a Monday','政策草案可被修改。',1,'context')]);
P('modish','Modish combines mode (“fashion, style”) with -ish and means fashionable or in the current style.',C('modish.s1','服饰风格','The boutique displayed modish jackets in bright colours, but the tailor noted that their cut might quickly go out of fashion.','精品店展示了颜色鲜亮的时髦夹克，但裁缝提醒它们的剪裁可能很快过时。','The boutique displayed modish jackets / in bright colours / but the tailor noted / that their cut might quickly go out of fashion.','modish 作形容词表示时髦、符合当下潮流，常带短暂流行的意味。','裁缝指出潮流可能变化，说明 modish 是当前时尚。'),M('The shop called the jackets modish although they were deliberately designed to imitate an obsolete style and were not fashionable.','The shop called the current-season jackets modish because they matched the latest style.','过时且不流行的服装不能称为时髦。'),[q('What was modish about the jackets?','they matched a current fashion','they were designed as rain gauges','they had been stored for a century','modish 表示符合当前时尚。'),q('What did the tailor warn?','the style might soon go out of fashion','the jackets were made of mineral','the colours could not be seen','时尚可能很快变化。'),q('Which outfit is modish?','one currently popular among designers','one rejected by current fashion','one worn only for safety','modish 指时下流行的风格。',1,'context'),q('Modish is built from mode plus?','-ish','-ment','-er','-ish 可构成“有……风格的”形容词。',1,'word-formation')]);
P('modulate','Modulate comes through Latin modulatus, from modulari (“measure, regulate”); it means to adjust a voice or signal, including changing a radio carrier.',[C('modulate.s1','声音调节','The narrator learned to modulate her voice, lowering it during the tense scene and speaking more brightly in the final paragraph.','旁白练习调节声音，在紧张场景中压低音量，并在最后一段更明快地说话。','The narrator learned to modulate her voice / lowering it during the tense scene / and speaking more brightly / in the final paragraph.','modulate 作及物动词可接 voice，表示调整音高、音量或语调。','声音随场景变化而调整。'),C('modulate.s2','信号调制','The transmitter modulates a carrier wave with the audio signal so the receiver can recover the broadcast.','发射器用音频信号调制载波，使接收器能够还原广播内容。','The transmitter modulates a carrier wave / with the audio signal / so the receiver can recover / the broadcast.','通信技术中 modulate 指把信息编码到载波信号中。','音频被加载到载波并由接收器还原。')],M('The narrator modulated her voice by keeping exactly the same pitch and volume throughout every scene.','The narrator modulated her voice by varying its pitch and volume to fit each scene.','完全不改变音高或音量不是调节声音。'),[q('How did the narrator change her voice?','she lowered it in the tense scene','she used one pitch for every scene','she stopped the broadcast','旁白根据场景调整声音。',1),q('What does the transmitter modulate?','a carrier wave with audio information','a voice with a fashion jacket','a water pipe with pressure','调制器把音频信号加载到载波。',2),q('Which use is the communication sense?','modulate a carrier wave','modulate a narrator’s tone','modulate a jacket size','载波调制是技术义。',2,'context'),q('Modulate is related to the idea of?','regulating or adjusting','molting feathers','making a monopoly','词源与调节、测量相关。',1,'word-formation')]);
P('modulation','Modulation comes from Latin modulatio, from modulari (“regulate”); it names adjustment of a voice or signal and, in music, a change from one key to another.',[C('modulation.s1','语音信号','The recording app applies gentle modulation to the singer’s voice to smooth changes in pitch without erasing the performance.','录音软件对歌手声音作轻微调节，使音高变化更平顺，同时保留演唱表现。','The recording app applies gentle modulation to the singer’s voice / to smooth changes in pitch / without erasing the performance.','modulation 作名词指声音或信号的调节变化。','处理音高变化而保留原始演唱，属于声音调节。'),C('modulation.s1','音乐转调','The final modulation moved the chorus from G major to A major, lifting the song into a brighter register.','最后的转调把副歌从 G 大调移到 A 大调，让歌曲进入更明亮的音区。','The final modulation moved the chorus / from G major to A major / lifting the song / into a brighter register.','音乐中 modulation 特指从一个调性转到另一个调性。','例句明确给出 G 大调转 A 大调。')],M('The final modulation kept the song in G major from beginning to end and changed no key.','The final modulation shifted the chorus from G major to A major.','没有更换调性就没有发生转调。'),[q('What did the recording app adjust?','the singer’s pitch changes','the chorus’s lyric sheet','the microphone stand height','modulation 可指声音变化的调节。',1),q('Which keys were involved in the final modulation?','G major and A major','C major and C major only','a minor key and no other key','例句说明从 G 大调转至 A 大调。',1),q('In music, modulation means?','changing from one key to another','repeating the same note only','removing the chorus','modulation 的音乐义是转调。',1,'meaning'),q('The app’s modulation aimed to?','smooth pitch changes','erase the singer entirely','raise the song’s ticket price','轻微声音调节使音高变化更平顺。',1,'context')]);
P('module','Module entered English through French module from Latin modulus, “small measure”; it names a self-contained unit of a larger system or course.',C('module.s1','课程单元','Students must complete the safety module online before entering the chemistry laboratory for their first practical class.','学生必须先在线完成安全课程单元，才能参加第一次化学实验课。','Students must complete the safety module online / before entering the chemistry laboratory / for their first practical class.','module 作名词可指课程或系统中相对独立的一部分。','在线安全课程是整个课程中的一个单元。'),M('The course called its safety module a complete degree that required no other classes.','The course called its online safety unit a module within the larger programme.','单个课程单元不是无需其他课程的完整学位。'),[q('What must students finish before entering the lab?','the online safety unit','the entire chemistry degree','a fashion show','安全 module 是进实验室前要完成的单元。'),q('A module is usually?','a self-contained part of a larger system or course','the whole university','a kind of weather','module 指较大系统中的独立单元。'),q('Which could be a software module?','a separate component that performs one function','a complete internet cable','a monarch’s crown','模块通常是具备特定功能的独立组件。',1,'context'),q('Why is the safety unit a module?','it is one part of the larger course','it replaces every course','it is a person’s job title','安全培训只是整体课程中的一部分。',1,'meaning')]);
P('moiety','Moiety came through Old French moite from Latin medietas (“half”), related to medius (“middle”); it means one of two equal parts or a share.',C('moiety.s1','遗产分配','The agreement assigned each sibling an equal moiety of the family land, dividing the estate into two matching shares.','协议把家族土地的各一半分给两名兄弟姐妹，将遗产分成相等两份。','The agreement assigned each sibling an equal moiety / of the family land / dividing the estate / into two matching shares.','moiety 作名词指整体的等分之一，常用于正式或法律语境。','土地被平均分为两份，各人获得一半。'),M('The deed granted one sibling a moiety equal to nine-tenths of the estate and left only one-tenth for the other.','The deed granted each sibling one moiety, an equal half of the estate.','九成与一成不是两个相等的 moiety。'),[q('How was the land divided?','into two equal shares','into nine shares for one sibling and one for the other','into a dozen unequal plots','moiety 指整体的二分之一。'),q('What did each sibling receive?','an equal half','the whole estate','only a tenth','协议让兄弟姐妹各得一半。'),q('Which phrase is closest to a moiety?','one of two equal portions','a tiny unrelated fragment','a complete double share','moiety 通常指两等分之一。',1,'meaning'),q('Moiety is related to a Latin word meaning?','half or middle','rainy season','soften anger','medietas 意为一半，词源与 middle 有关。',1,'word-formation')]);
P('moist','Moist is from Old French moiste, perhaps related to Latin musteus (“fresh, new”); it describes something slightly wet or weather rich in water vapour.',[C('moist.s1','食物质地','The baker covered the cake with a cloth so the sponge would stay moist until the guests arrived.','面包师用布盖住蛋糕，让海绵蛋糕在客人到来前保持湿润。','The baker covered the cake with a cloth / so the sponge would stay moist / until the guests arrived.','moist 描述含有少量水分、未变干的状态。','盖住蛋糕可防止水分散失。'),C('moist.s2','湿润天气','The coastal air felt moist after overnight fog, and the windows collected a thin film of condensation.','夜间起雾后，沿海空气显得潮湿，窗户上凝结了一层薄水汽。','The coastal air felt moist after overnight fog / and the windows collected / a thin film of condensation.','moist 也可形容空气含水汽较多、潮湿。','雾后空气潮湿并在窗上形成冷凝水。')],M('The baker said the cake remained moist even though it was dry, crumbly, and had lost all its water.','The baker kept the cake moist by covering it before it dried out.','完全干燥易碎与 moist 的湿润状态相反。'),[q('Why did the baker cover the cake?','to keep the sponge from drying out','to make it lose all moisture','to freeze it solid','保持湿润是盖布的目的。',1),q('What formed on the windows after fog?','a thin film of condensation','a layer of dry flour','a sugar mould','水汽凝结在窗户上。',2),q('Which item should stay moist?','a sponge cake','a dry paper map','a powder packet','蛋糕保持湿润可防止口感变干。',1,'context'),q('Moist most nearly means?','slightly wet','completely dry','made of metal','moist 指含有一定水分。')]);
P('moisten','Moisten is moist plus -en, a verb-forming suffix meaning to make or become slightly wet.',C('moisten.s1','润湿材料','Moisten the cloth with clean water before wiping the camera lens so dust does not scratch the glass.','擦相机镜头前先用清水润湿布，以免灰尘划伤玻璃。','Moisten the cloth with clean water / before wiping the camera lens / so dust does not scratch the glass.','moisten 作及物动词，常用 moisten something with liquid。','少量清水使布变湿，用于安全擦拭镜头。'),M('The instructions said to moisten the cloth by leaving it completely dry.','The instructions said to moisten the cloth with a little clean water.','干燥的布没有被润湿。'),[q('What should be moistened?','the cloth','the camera’s battery','the glass with dry dust','说明要求润湿擦拭布。'),q('What liquid should be used?','clean water','molasses','hot cooking oil','例句指定清水。'),q('Why moisten the cloth first?','to reduce the chance that dust scratches the lens','to add dust to the glass','to remove the camera’s modem','湿布帮助避免灰尘刮伤镜片。'),q('The suffix -en in moisten helps form a?','verb meaning make moist','plural noun','person who models clothes','-en 构成使某物变湿的动词。',1,'word-formation')]);
P('moisture','Moisture comes from moist plus -ure and names small amounts of water in the air, on a surface, or within a material.',C('moisture.s1','储物环境','The cabinet’s humidity sensor alerted staff when moisture began to collect on the archive boxes.','湿度传感器在档案盒开始受潮时提醒了工作人员。','The cabinet’s humidity sensor alerted staff / when moisture began to collect / on the archive boxes.','moisture 作不可数名词，指环境、表面或物体中的水分。','档案盒上的水分触发湿度警报。'),M('The archive boxes were damaged by moisture even though the room and their surfaces contained no water at all.','The archive boxes were damaged after moisture collected on their surfaces.','没有任何水分就不能说物件受潮。'),[q('What alerted the staff?','moisture collecting on the archive boxes','a new fashion trend','a modem changing its signal','档案盒表面出现水分触发传感器。'),q('Moisture is?','water present in air or on a surface','a dry mineral powder','a measure of temperature','moisture 指水分或湿气。'),q('Which situation shows excess moisture?','condensation forming inside a cupboard','a clean dry book on a shelf','a radio signal changing frequency','柜内冷凝水体现湿气过多。',1,'context'),q('Moisture is usually treated as?','an uncountable noun','a plural-only verb','a proper name','moisture 通常作不可数名词。',1,'countability')]);
P('moisturizer','Moisturizer is formed from moisturize plus -er and names a cream or lotion applied to reduce dryness of the skin.',C('moisturizer.s1','护肤用品','After washing her hands repeatedly at work, Salma applied moisturizer to stop the skin around her knuckles from cracking.','萨尔玛工作时反复洗手后涂了润肤霜，防止指关节周围的皮肤干裂。','After washing her hands repeatedly at work / Salma applied moisturizer / to stop the skin around her knuckles / from cracking.','moisturizer 作可数名词，指用于皮肤保湿的乳霜或乳液。','洗手导致皮肤干燥，润肤霜用于减少干裂。'),M('Salma applied moisturizer to make her already cracked skin even drier.','Salma applied moisturizer to reduce dryness and protect the skin.','润肤产品用于减少皮肤干燥，不是加重干燥。'),[q('Why did Salma apply moisturizer?','to prevent dry skin from cracking','to make her hands dirtier','to clean the archive boxes','润肤霜帮助减轻干燥和开裂。'),q('Where was the skin dry?','around her knuckles','on the camera lens','inside the water network','例句指出指关节周围皮肤干裂。'),q('Which product is a moisturizer?','a skin lotion used to reduce dryness','a detergent for washing dishes only','a carrier-wave transmitter','保湿乳液用于皮肤。',1,'context'),q('Moisturizer is related to which verb?','moisturize','moderate','monopolize','moisturizer 由 moisturize 派生。',1,'word-formation')]);
P('molar','Molar comes from Latin molaris (“of a mill”), from mola (“millstone”); it names a large back tooth used to grind food.',C('molar.s1','牙齿结构','The dentist found a small cavity in the lower molar, the broad tooth the patient used to chew tough food.','牙医在下方臼齿上发现一个小蛀洞；病人用这颗宽大的牙齿咀嚼硬食物。','The dentist found a small cavity in the lower molar / the broad tooth / the patient used / to chew tough food.','molar 作名词指口腔后部用于磨碎食物的宽大牙齿。','臼齿负责咀嚼、磨碎较硬食物。'),M('The dentist called the pointed front tooth a molar even though it was used mainly for biting.','The dentist called the broad back tooth a molar because it grinds food.','尖锐前牙不是用于磨碎食物的臼齿。'),[q('Where was the cavity?','in a lower back tooth','in the tongue','in the jaw joint','molar 是后部臼齿。'),q('What is a molar’s main function?','grinding food while chewing','hearing sounds','modulating speech signals','臼齿用于磨碎食物。'),q('Which tooth is a molar?','a broad tooth near the back of the mouth','a pointed front incisor','a milk product','宽大的后牙是 molar。',1,'context'),q('Molar comes from a Latin word connected with?','a mill or grinding','a rainy season','a small measure','molaris 与 millstone 有关，呼应磨碎功能。',1,'word-formation')]);
P('molasses','Molasses came through Portuguese melaço from Latin mel (“honey”); it is the thick dark syrup left when sugar is processed.',C('molasses.s1','烘焙食材','The recipe uses molasses to give the ginger biscuits their dark colour and rich, slightly bitter sweetness.','食谱用糖蜜为姜味饼干增添深色和浓郁、略带苦味的甜味。','The recipe uses molasses / to give the ginger biscuits their dark colour / and rich, slightly bitter sweetness.','molasses 通常作不可数名词，指制糖过程中留下的浓稠糖浆。','深色糖浆为饼干增色并带来独特甜味。'),M('The baker replaced the thick dark molasses with clear drinking water to preserve the same sweetness and colour.','The baker used a spoonful of molasses to add dark colour and deep sweetness.','清水没有糖蜜的浓稠质地、颜色和甜味。'),[q('What did molasses add to the biscuits?','dark colour and rich sweetness','a sour milk flavour','a radio signal','糖蜜使饼干颜色深、味道浓甜。'),q('What is molasses?','thick syrup left from sugar processing','a large back tooth','a kind of weather','molasses 是制糖留下的浓稠糖浆。'),q('Which ingredient is molasses?','dark sticky sugar syrup','dry wheat flour','plain water','深色黏稠糖浆是 molasses。',1,'context'),q('Molasses is generally used as?','an uncountable noun','a plural verb','a person’s title','通常说 some molasses，不用复数计数。',1,'countability')]);
P('mold','Mold has separate histories: the fungus sense is recorded from Middle English and may relate to words for dampness; the shaping-form sense came through French from Latin modulus (“measure, model”).',[C('mold.s1','食物霉菌','Green mold appeared on the forgotten bread after it had been left in the warm cupboard for several days.','面包在温暖橱柜里遗忘了几天后，长出了绿色霉菌。','Green mold appeared on the forgotten bread / after it had been left / in the warm cupboard / for several days.','mold 作名词指潮湿或腐败物表面的霉菌，美式常拼 mold，英式常写 mould。','发霉面包上的绿色菌斑对应真菌义。'),C('mold.s2','成形模具','Pour the warm chocolate into a heart-shaped mold and leave it to set before removing the pieces.','把温热巧克力倒入心形模具，待凝固后再取出成品。','Pour the warm chocolate into a heart-shaped mold / and leave it to set / before removing the pieces.','mold 作名词也可指用来成形或铸造的模具。','巧克力凝固后会形成模具的形状。'),C('mold.s3','类型模式','The novel broke the mold of the usual detective story by revealing the culprit in its opening chapter.','这部小说打破了常见侦探故事的模式，在第一章就揭示了罪犯。','The novel broke the mold of the usual detective story / by revealing the culprit / in its opening chapter.','break the mold 指打破既有类型或惯例。','提前揭晓罪犯打破了传统侦探故事套路。'),C('mold.s4','塑造成形','The craft teacher showed the children how to mold soft clay into a small bowl.','手工老师示范如何把软陶塑造成小碗。','The craft teacher showed the children / how to mold soft clay / into a small bowl.','mold 作及物动词表示塑形或使某物形成特定样子。','软陶被塑造成碗。')],M('The baker poured chocolate into a mold but claimed the mold was the green fungus growing on bread.','The baker poured chocolate into a shaped container and let it set.','成形模具与面包上的真菌是 mold 的不同义项，不能混为一谈。','confusable'),[q('What grew on the forgotten bread?','green mold fungus','a chocolate shape','a detective story','面包上出现绿色霉菌。',1),q('Why pour chocolate into a mold?','to give it a particular shape','to grow fungus on it','to reveal a story’s culprit','模具用于让巧克力凝固成型。',2),q('Break the mold of a genre means?','depart from its usual pattern','make a new baking container','cover food with fungus','此短语比喻打破固定类型。',3,'collocation'),q('In mold soft clay into a bowl, mold is?','a verb meaning shape it','a noun meaning fungus','an adverb meaning slightly','动词 mold 表示塑造成形。',4,'grammar')]);
P('moldy','Moldy is mold plus -y and means covered with mold or spoiled by fungal growth.',C('moldy.s1','食品变质','The café discarded the moldy oranges after a white fuzz spread across their skins in the storage crate.','储物箱里的橙子表面长出白色绒毛后，咖啡馆把发霉的橙子丢弃了。','The café discarded the moldy oranges / after a white fuzz spread / across their skins / in the storage crate.','moldy 作形容词描述长霉、因真菌而变质的东西；英式拼法 mouldy。','白色菌丝长在橙皮上说明水果发霉。'),M('The café sold moldy oranges that were fresh, spotless, and free of any fungal growth.','The café discarded oranges covered with mold.','没有真菌生长的干净水果不能称为 moldy。'),[q('What showed the oranges were moldy?','white fuzz spread over their skins','their bright clean surfaces','their lack of any spots','白色绒毛是真菌生长迹象。'),q('What did the café do with the oranges?','discarded them','used them to make a clay mold','sent them to a monastery','发霉水果被丢弃。'),q('Which food is moldy?','bread with visible green fungus','freshly baked bread with a clean crust','a dry sugar packet','可见霉菌的食物是 moldy。',1,'context'),q('Which is the common British spelling?','mouldy','moldie','mouldey','英式英语常写 mouldy。',1,'spelling')]);
P('mole','Mole in this entry is the espionage sense, from the metaphor of an agent burrowing secretly into an organisation; the word has other unrelated dictionary senses.',C('mole.s1','情报活动','The investigators discovered a mole inside the department who had been passing confidential schedules to a rival agency.','调查人员发现部门内部有一名内鬼，长期把机密日程传给竞争机构。','The investigators discovered a mole inside the department / who had been passing confidential schedules / to a rival agency.','mole 作名词指秘密渗透组织并向外传递情报的人。','泄露机密给对手符合间谍义。'),M('The investigators called a loyal employee a mole even though the employee had never disclosed information or worked for another agency.','The investigators called the employee a mole after finding proof that confidential files had been passed to a rival agency.','没有泄密或为外部机构工作的证据，不能据此认定其为内鬼。'),[q('What had the mole been passing outside?','confidential schedules','chocolate moulds','public weather reports','内鬼把机密日程传给了对手。'),q('Where was the mole located?','inside the department','at a public fashion show','in a garden tunnel','间谍秘密潜伏在该部门内部。'),q('Which person is a mole?','an employee secretly leaking company plans to a rival','a loyal worker following every security rule','a visitor who reads a public notice','mole 的间谍义是秘密泄露情报的内线。',1,'context'),q('The espionage use of mole suggests someone who?','burrows secretly into an organisation','measures small quantities','works as a dentist','该比喻强调秘密潜入组织内部。',1,'word-formation')]);
P('molecular','Molecular is molecule plus -ar and means relating to molecules, the small units that make up many substances.',C('molecular.s1','科学分析','The laboratory used molecular analysis to identify traces of plant DNA left on the ancient tool.','实验室用分子分析识别古代工具上残留的植物 DNA。','The laboratory used molecular analysis / to identify traces of plant DNA / left on the ancient tool.','molecular 作形容词修饰 analysis，表示在分子层面进行的分析。','DNA 痕迹通过分子层面的技术识别。'),M('The laboratory described a molecular analysis as a study that never examined molecules or chemical material.','The laboratory examined molecular evidence, including the plant DNA traces.','完全不研究分子或化学材料的分析不能称为 molecular。'),[q('What did molecular analysis identify?','traces of plant DNA','the tool’s price','a monastery’s age','分子分析检测出植物 DNA 痕迹。'),q('Molecular means relating to?','molecules','monarchs','modest clothing','molecular 是与 molecule 有关的形容词。'),q('Which study is molecular?','examining DNA at the level of its chemical units','counting whole trees in a forest','measuring a bus route','分子研究关注物质的分子层面。',1,'context'),q('Molecular is formed from molecule plus?','-ar','-ist','-hood','-ar 构成形容词 molecular。',1,'word-formation')]);
P('molecule','Molecule came from French molécule and Latin molecula, a diminutive of moles (“mass”); it names a group of atoms bonded together.',C('molecule.s1','化学结构','A water molecule contains two hydrogen atoms bonded to one oxygen atom, giving it the formula H₂O.','一个水分子由两个氢原子与一个氧原子结合而成，化学式为 H₂O。','A water molecule contains two hydrogen atoms / bonded to one oxygen atom / giving it the formula H₂O.','molecule 作名词指由两个或更多原子结合形成的基本粒子。','例句给出一个水分子的组成。'),M('A water molecule contains one atom of hydrogen and no oxygen.','A water molecule contains two hydrogen atoms bonded to one oxygen atom.','水分子 H₂O 含两个氢原子和一个氧原子。','measurement'),[q('What is the formula of the water molecule?','H₂O','CO₂','O₃','水分子的化学式是 H₂O。'),q('How many hydrogen atoms are in one water molecule?','two','one','three','H₂O 中有两个氢原子。'),q('A molecule is?','a group of bonded atoms','a single fashion style','a type of secret agent','molecule 指结合在一起的原子群。'),q('What is bonded to the two hydrogen atoms in water?','one oxygen atom','one carbon atom','two calcium atoms','水分子由两个氢和一个氧组成。',1,'context')]);
P('molest','Molest comes from Latin molestare, “to trouble or annoy”; modern English most often means to harass or abuse someone, including sexually.',C('molest.s1','人身安全','The complaint stated that an adult had molested the teenager, and the school immediately contacted safeguarding officers and the family.','投诉称一名成年人猥亵了这名青少年，学校立即联系了学生保护专员和家属。','The complaint stated / that an adult had molested the teenager / and the school immediately contacted / safeguarding officers and the family.','molest 作及物动词，现代语境常指对人实施性侵害或严重骚扰；属于严肃指控。','学校启动保护程序表明此处是对未成年人的严重侵害指控。'),M('The report said the adult molested the teenager but then clarified that no harassment or abuse had occurred.','The report said the adult molested the teenager and referred the allegation for safeguarding investigation.','若没有骚扰或侵害事实，molest 这一严重指控就不成立。','word-choice'),[q('Whom did the complaint say had been molested?','the teenager','the school building','the family’s car','投诉针对的是青少年遭受侵害。'),q('What did the school do immediately?','contacted safeguarding officers and the family','published the teenager’s private details','dismissed the report without action','学校联系保护专员和家属。'),q('Molest is a serious verb meaning to?','harass or abuse a person','adjust a radio carrier wave','make a surface slightly wet','该词指骚扰或侵害，属于严重用语。',1,'register'),q('Which response is appropriate to an allegation of molestation?','refer it to safeguarding professionals and follow procedures','treat it as a harmless joke','share private details publicly','严肃的侵害指控需要通过保护程序处理。',1,'context')]);
P('mollify','Mollify came from Latin mollificare, “make soft,” based on mollis (“soft”); it means to soothe anger or make a demand less severe.',[C('mollify.s1','平息怒气','The manager offered a sincere apology and a refund to mollify customers angered by the cancelled deliveries.','经理诚恳道歉并退款，以安抚因配送取消而生气的顾客。','The manager offered a sincere apology and a refund / to mollify customers / angered by the cancelled deliveries.','mollify 作及物动词，后接被安抚的人或情绪。','道歉和退款试图平息顾客怒气。'),C('mollify.s2','缓和要求','The mediator’s proposal mollified the union’s demand for an immediate walkout by setting a firm date for negotiations.','调解员提出明确谈判日期，缓和了工会立即罢工的要求。','The mediator’s proposal mollified the union’s demand / for an immediate walkout / by setting a firm date / for negotiations.','mollify 也可指减轻要求或批评的强度。','明确谈判安排让立即罢工的要求不再那么强烈。')],M('The apology mollified customers by insulting them again and refusing any remedy.','The apology mollified customers by accepting responsibility and offering a refund.','再次侮辱顾客并拒绝补救不会安抚他们。'),[q('What helped mollify the angry customers?','an apology and refund','another cancellation','an insult and refusal','道歉并退款用来安抚顾客。',1),q('What did the mediator’s proposal soften?','the union’s demand for an immediate walkout','the date of the old delivery','the manager’s job title','方案缓和了工会立即罢工的要求。',2),q('Mollify most nearly means?','calm or soften','make wetter','turn into a model','mollify 表示安抚或缓和。'),q('Which action might mollify an angry passenger?','explain the delay and offer a practical remedy','deny the delay while shouting','cancel all information desks','解释情况并提供补救可能平息怒气。',1,'context')]);
P('mollusk','Mollusk came through French mollusque from Latin molluscus (“soft”); it names an invertebrate such as a snail, clam, squid, or octopus.',[C('mollusk.s1','动物分类','The biology class observed an octopus as a mollusk, noting its soft body and arms lined with suckers.','生物课把章鱼归为软体动物，并观察了它柔软的身体和布满吸盘的腕足。','The biology class observed an octopus as a mollusk / noting its soft body / and arms lined with suckers.','mollusk 作名词指软体动物门成员，既包括有壳动物也包括章鱼等。','章鱼无外壳但属于软体动物。'),C('mollusk.s2','食用贝类','The seafood stall labelled its mussels as mollusks and kept them chilled until customers ordered.','海鲜摊把贻贝标为软体动物，并冷藏保存至顾客点单。','The seafood stall labelled its mussels as mollusks / and kept them chilled / until customers ordered.','mollusk 也可在食品语境泛指可食用的贝类软体动物。','贻贝属于可食用软体动物。')],M('The biology class classified an octopus as a mammal because it has arms.','The biology class classified the octopus as a mollusk, an invertebrate with a soft body.','章鱼是无脊椎软体动物，不是哺乳动物。','confusable'),[q('Which animal did the class study?','an octopus','a monkey','a molar tooth','章鱼属于软体动物。',1),q('What did the stall keep chilled?','mussels','a modem','a clay mould','贻贝作为海鲜冷藏。',2),q('Which is a mollusk without an external shell?','an octopus','a lamb','a sparrow','章鱼是无外壳软体动物。',1,'context'),q('Mollusk comes from Latin molluscus, meaning?','soft','fashionable','half','词源 molluscus 意为柔软。',1,'word-formation')]);
})();

(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('molt','Molt comes from Old English mutian, “to change,” related to Latin mutare; its spelling acquired an unetymological l. It names the shedding process or the act of losing feathers, hair, or a shell.',[C('molt.s1','生物过程','The wildlife centre recorded the eagle’s annual molt, collecting the old feathers for a study of its growth cycle.','野生动物中心记录了鹰每年的换羽过程，并收集脱落的旧羽毛研究其生长周期。','The wildlife centre recorded the eagle’s annual molt / collecting the old feathers / for a study of its growth cycle.','molt 作名词指鸟、昆虫或哺乳动物脱落外层结构的过程。','记录年度换羽并收集旧羽毛，对应名词义。'),C('molt.s2','脱落换羽','As the young snake grew, it molted its old skin and emerged with a fresh outer layer.','幼蛇长大时蜕去了旧皮，露出新的外层。','As the young snake grew / it molted its old skin / and emerged with a fresh outer layer.','molt 作动词表示脱去羽毛、毛发或旧壳；英式英语也常拼作 moult。','蛇脱去旧皮是动词义。')],M('The snake molted its old skin by keeping the same outer layer throughout its growth.','The snake molted its old skin as it grew.','保留旧皮没有发生蜕皮。','meaning'),[q('What did the centre record?','the eagle’s annual shedding of feathers','the eagle’s migration route','the snake’s new nest','molt 作名词指脱换羽毛等外层结构的过程。',1),q('What happened as the snake grew?','it shed its old skin','it grew a set of feathers','it changed the eagle’s route','蛇蜕下旧皮。',2),q('Which sentence uses molt as a verb?','The crab molted its shell.','The crab’s molt lasted a week.','The crab studied a map.','molted 在此表示脱去旧壳。',2,'grammar'),q('Which spelling is also common in British English?','moult','moltle','mould','moult 是常见英式变体拼法。',2,'spelling')]);
P('molten','Molten is the archaic strong past participle of Old English meltan, “become liquid through heat”; it now describes melted or glowing-hot material.',[C('molten.s1','熔融材料','Workers poured molten glass into a mould and shaped it before the material cooled.','工人把熔融玻璃倒进模具，并在材料冷却前塑形。','Workers poured molten glass into a mould / and shaped it / before the material cooled.','molten 常修饰受热而成为液体的金属、玻璃或岩石。','玻璃在模具中冷却前仍处于熔融状态。'),C('molten.s2','炽热发光','The forge’s open door revealed a pool of molten metal glowing orange beneath the furnace.','透过锻炉敞开的门，可以看到炉下有一池橙红发光的炽热金属。','The forge’s open door revealed a pool of molten metal / glowing orange / beneath the furnace.','molten 也可着重表示物质炽热发光。','金属发橙光强调其高温。')],M('The workers poured molten glass after it had cooled into a hard, solid block.','The workers poured molten glass while it was still liquid and hot.','已经冷却变硬的玻璃不是熔融状态。'),[q('Why was the glass poured into a mould?','it was still liquid and could be shaped','it had already frozen solid','it was a type of fuel','熔融玻璃在冷却前可塑形。',1),q('What colour did the hot metal glow?','orange','blue and cold','transparent green','例句明确说金属发橙光。',2),q('Which material is molten?','iron heated until it flows as a liquid','a cold metal bar','a dry wooden handle','受热液化的铁是 molten。',1,'context'),q('Molten is historically a participle of which verb?','melt','mold','molt','molten 是 melt 的古老强变化过去分词。',1,'word-formation')]);
P('mom','Mom was recorded in American English by 1867, perhaps as a shortening of mommy; related mother-words often echo early child speech.',C('mom.s1','家庭称呼','Jordan called his mom after landing, telling her that the flight had arrived safely and his luggage was with him.','乔丹落地后给妈妈打电话，告诉她航班已安全抵达，行李也在身边。','Jordan called his mom after landing / telling her that the flight had arrived safely / and his luggage was with him.','mom 是美式英语中对 mother 的非正式称呼。','通话中的家庭称呼是 mom。'),M('In the American dialogue, Jordan called his mother “mom” as a formal title for a government official.','In the American dialogue, Jordan called his mother “mom,” an informal family term.','mom 是家庭中的非正式称呼，不是政府职务头衔。','register'),[q('Whom did Jordan call after landing?','his mother','the airline’s pilot','the baggage officer','mom 是打给母亲的家庭称呼。'),q('Which setting best fits mom?','an informal conversation at home','a formal legal title for a judge','a scientific unit','mom 是非正式家庭用语。',1,'register'),q('Mom is especially associated with which variety of English?','American English','only formal British legal English','ancient Greek','该词尤见于美式英语。',1,'context'),q('In “my mom called,” mom functions as a?','noun for a family member','verb meaning melt','plural adjective','mom 在句中是指家庭成员的名词。',1,'grammar')]);
P('moment','Moment came through Old French from Latin momentum, “movement, moving power”; English uses it for a brief span, a point in time, or importance.',[C('moment.s1','短暂片刻','Please wait a moment while the pharmacist checks whether the prescription is ready.','请稍等片刻，药剂师要确认处方是否备好。','Please wait a moment / while the pharmacist checks / whether the prescription is ready.','moment 作名词指持续很短的一段时间。','等待药剂师确认处方只需短暂片刻。'),C('moment.s2','具体时机','At the moment the bell rang, the students were lining up quietly outside the hall.','铃声响起的那一刻，学生们正在礼堂外安静排队。','At the moment the bell rang / the students were lining up quietly / outside the hall.','moment 也可指某一具体时刻或时机。','铃声响起是时间线上明确的一刻。'),C('moment.s3','重要性','The discovery was of great moment because it changed how doctors treated the disease.','这项发现意义重大，因为它改变了医生治疗这种疾病的方式。','The discovery was of great moment / because it changed how doctors treated the disease.','of great moment 是较正式的搭配，表示意义重大。','改变治疗方式说明发现具有重要性。')],M('The discovery was of great moment, but it had no importance and changed nothing.','The discovery was of great moment because it changed medical practice.','of great moment 表示重要，和“毫无重要性”相矛盾。','collocation'),[q('How long should the customer wait?','a short time','the whole afternoon','until the next Monday','wait a moment 指短暂等待。',1),q('When did the students line up?','at the time the bell rang','a month after the term ended','before the school was built','此处 moment 指铃声响起的具体时刻。',2),q('A discovery “of great moment” is?','very important','brief and unimportant','a particular clock','该搭配表示意义重大。',3,'collocation'),q('Which phrase most clearly means “for a short time”?','wait a moment','of great moment','at that moment in history','wait a moment 表示稍等片刻。',1,'meaning')]);
P('momentarily','Momentarily was formed from momentary plus -ly and means “for a moment” or “briefly.”',C('momentarily.s1','短暂地','The lights flickered momentarily during the storm, then returned before the emergency generator started.','暴风雨期间灯光短暂闪烁，随后在应急发电机启动前恢复了。','The lights flickered momentarily / during the storm / then returned / before the emergency generator started.','momentarily 作副词修饰 flickered，强调动作持续时间很短。','灯光只闪了一小会儿便恢复。'),M('The lights flickered momentarily for several uninterrupted hours.','The lights flickered momentarily for only a brief instant.','持续数小时与 momentarily 表示的短暂时间不符。'),[q('How long did the lights flicker?','briefly','for several uninterrupted hours','for an entire season','momentarily 表示只持续片刻。'),q('What happened after the brief flicker?','the lights returned','the building was demolished','the storm became a television','灯光随后恢复。'),q('In the sentence, momentarily modifies?','the verb flickered','the noun storm','the adjective emergency','副词 momentarily 修饰动作 flickered。',1,'grammar'),q('Which is closest in meaning to momentarily here?','for a short time','permanently','with great importance','例句中的词表示短暂地。',1,'meaning')]);
P('momentary','Momentary comes from Late Latin momentarius, “lasting a moment,” based on Latin momentum; it describes something brief.',C('momentary.s1','短暂反应','A momentary pause followed the announcement, and then the audience began applauding.','宣布消息后现场短暂停顿，随后观众开始鼓掌。','A momentary pause followed the announcement / and then the audience began applauding.','momentary 作形容词修饰 pause，表示持续极短。','停顿只维持片刻，随后掌声响起。'),M('A momentary pause continued without interruption for the entire week.','A momentary pause lasted only briefly before the applause began.','持续整整一周的停顿不能称为 momentary。'),[q('What followed the announcement?','a brief pause','a permanent silence','a month-long concert','momentary pause 是短暂停顿。'),q('What did the audience do after the pause?','began applauding','left before the announcement','started a weather report','例句中观众随后鼓掌。'),q('Momentary is a/an?','adjective describing a brief event','adverb describing a loud voice','noun for a key ruler','momentary 是修饰名词的形容词。',1,'grammar'),q('Which event is momentary?','a blink lasting a fraction of a second','a year-long construction project','a permanent change','瞬间眨眼属于极短事件。',1,'context')]);
P('momentous','Momentous was formed from moment plus -ous; it describes an event or turning-point time of exceptional importance.',[C('momentous.s1','重大事件','The treaty was a momentous agreement that ended the border conflict and reshaped relations between the two countries.','这项条约意义重大，它结束了边境冲突并重塑两国关系。','The treaty was a momentous agreement / that ended the border conflict / and reshaped relations / between the two countries.','momentous 修饰影响深远的重要事件或决定。','条约带来重大政治后果。'),C('momentous.s2','关键时刻','For the small company, the day its first product reached shops was a momentous moment in its history.','对这家小公司而言，首款产品进入商店的那天是其历史上的关键时刻。','For the small company / the day its first product reached shops / was a momentous moment / in its history.','momentous moment 指具有转折意义的重要时刻。','首款产品上市标志公司发展的关键节点。')],M('The treaty was momentous because it had no lasting effect and changed nothing.','The treaty was momentous because it ended the conflict and changed relations.','没有影响或变化不符合 momentous 的重大意义。'),[q('What did the treaty do?','ended the border conflict','started an unrelated fashion show','changed the day of the week','条约结束冲突并重塑关系。',1),q('Why was launch day momentous for the company?','its first product reached shops','the office lights flickered briefly','a routine receipt was filed','首款产品上市是公司的关键时刻。',2),q('A momentous decision is likely to?','have major consequences','last only one second','be impossible to remember','momentous 表示影响重大的。',1,'meaning'),q('Which is a momentous event for a city?','the opening of its first hospital','a routine light switching on','a brief pause in a meeting','重大公共设施启用可能改变城市生活。',1,'context')]);
P('momentum','Momentum is Latin momentum, “movement or moving power”; it names physical quantity of motion and, figuratively, force that keeps progress going.',[C('momentum.s1','物理运动量','The heavier cart gained more momentum as it rolled downhill, so the safety barrier had to be stronger.','较重的手推车下坡时获得了更大的动量，因此安全挡板必须更结实。','The heavier cart gained more momentum / as it rolled downhill / so the safety barrier / had to be stronger.','物理学中 momentum 指运动物体的动量，和质量、速度有关。','较重物体滚动时动量更大，冲击风险随之增加。'),C('momentum.s2','进展势头','After the first successful trial, the research team built momentum and completed the remaining tests ahead of schedule.','首次试验成功后，研究团队势头渐起，提前完成了其余测试。','After the first successful trial / the research team built momentum / and completed the remaining tests / ahead of schedule.','figurative build momentum 指逐渐形成推动进展的势头。','成功试验后工作加快并提前完成。')],M('The campaign built momentum when every supporter stopped taking part and all progress ceased.','The campaign built momentum as more volunteers joined and its reach expanded.','参与者退出、进展停滞意味着势头减弱。'),[q('Why was the cart’s barrier made stronger?','the cart had gained more momentum downhill','the cart had stopped moving','the road had become shorter','较重手推车下坡获得更大动量。',1),q('What helped the team build momentum?','a successful first trial','a cancelled research plan','a broken thermometer','首次试验成功推动后续工作。',2),q('In a project, build momentum means?','gain increasing force or progress','calculate an object’s mass only','stop all activity','比喻义指进展势头增强。',2,'meaning'),q('Which example uses the physical sense?','a moving cart’s mass and speed determine its momentum','a team gains momentum after early success','a campaign builds public support','物理动量与质量和运动速度有关。',1,'context')]);
P('monarch','Monarch came through Old French and Late Latin from Greek monarkhēs, “one who rules alone.”',C('monarch.s1','君主身份','The monarch opened parliament with a short speech, while elected ministers remained responsible for day-to-day government.','君主以简短演讲为议会开幕，而日常政府事务仍由民选部长负责。','The monarch opened parliament with a short speech / while elected ministers remained responsible / for day-to-day government.','monarch 作可数名词指国王或女王等君主。','君主出席议会开幕仪式，部长负责日常政务。'),M('The country’s elected minister was called its monarch even though the head of state was a hereditary queen.','The country’s hereditary queen was the monarch, while an elected minister led the government.','政府部长与世袭君主是不同职务。','confusable'),[q('Who opened parliament?','the monarch','the research assistant','the town’s weather monitor','例句中君主为议会开幕。'),q('Who handled day-to-day government?','elected ministers','the monarch alone','the parliament’s audience','日常政务由民选部长负责。'),q('A monarch is?','a king or queen who rules a country','a person who monitors a laboratory','a religious residence','monarch 指国王或女王。',1,'meaning'),q('Which person is a monarch?','a queen serving as the country’s sovereign','a minister elected to run one department','a monk living in a monastery','君主是国家的国王或女王。',1,'context')]);
P('monarchy','Monarchy came through Old French and Late Latin from Greek monarkhia, literally “rule by one.”',[C('monarchy.s1','政体制度','The constitution preserved the monarchy but limited the sovereign’s powers and assigned most policy decisions to parliament.','宪法保留了君主制，但限制君主权力，并把大多数政策决定交给议会。','The constitution preserved the monarchy / but limited the sovereign’s powers / and assigned most policy decisions / to parliament.','monarchy 作名词指以君主为国家元首的政体。','宪法规定了君主制及其权力限制。','政治'),C('monarchy.s2','君主国','The island became a constitutional monarchy after its new charter retained the king as head of state.','新宪章保留国王作为国家元首后，这座岛成为君主国。','The island became a constitutional monarchy / after its new charter / retained the king / as head of state.','monarchy 也可指实行君主制的国家。','这座岛本身成为保留国王的君主国。','政治')],M('The constitution abolished the monarchy while claiming that the country still had a hereditary king as head of state.','The constitution retained the monarchy and kept the hereditary king as head of state.','保留世袭君主作为国家元首说明君主制并未废除。'),[q('What did the constitution preserve?','the system of monarchy','an elected republic with no monarch','a religious order','宪法保留了君主制。',1),q('What became a constitutional monarchy?','the island','the charter itself','the parliament’s policy office','例句说岛屿国家成为君主国。',2),q('Monarchy can refer to?','a system ruled by a monarch','a country ruled by a monarch','both a system and such a country','词既指政体，也可指君主国。',1,'meaning'),q('Which change would abolish a monarchy?','replacing the hereditary sovereign with an elected head of state','limiting a king’s ceremonial powers','keeping the monarch as head of state','废除君主制要取消君主作为国家元首的制度。',1,'context')]);
P('monastery','Monastery came through Old French and Late Latin from Greek monastērion, “place for living alone,” from monazein, “live alone.”',C('monastery.s1','宗教共同体','The hilltop monastery has a small library where the monks copy manuscripts and welcome visitors during the day.','山顶修道院设有小图书室，僧侣在那里抄写手稿，并在白天接待访客。','The hilltop monastery has a small library / where the monks copy manuscripts / and welcome visitors / during the day.','monastery 作名词指修士共同生活的宗教住所。','僧侣在此共同居住并从事宗教生活。','宗教'),M('The hikers slept in a monastery that was actually a crowded public train station with no religious community.','The hikers visited a monastery where a community of monks lived and worshipped.','没有宗教共同体的车站不是修道院。','confusable'),[q('Who lives at the monastery?','a community of monks','a team of elected ministers','a group of airline pilots','monastery 是僧侣共同居住的地方。'),q('What do the monks do in its library?','copy manuscripts','melt glass in a factory','monitor a bus route','僧侣在图书室抄写手稿。'),q('Which place is a monastery?','a residence shared by monks','a short period of time','a ruler’s parliament','修道院是宗教共同体住所。',1,'meaning'),q('Monastery is historically connected with a Greek word meaning?','to live alone','to move a pointer','to make a mixture','希腊词根 monazein 有独居之意。',1,'word-formation')]);
P('Monday','Monday comes from Old English mōnandæg, “day of the moon,” translating an older Germanic name.',C('Monday.s1','星期名称','The clinic is closed on Monday, so the patient booked a follow-up appointment for Tuesday instead.','诊所星期一休息，因此病人改约星期二复诊。','The clinic is closed on Monday / so the patient booked a follow-up appointment / for Tuesday instead.','Monday 是专有名词，首字母大写，表示星期一。','例句将 Monday 与 Tuesday 区分为相邻日期。'),M('The notice said the clinic opens Monday, then listed Monday as the day after Tuesday.','The notice said the clinic opens Monday, the day before Tuesday.','Monday 在一周中先于 Tuesday。','meaning'),[q('When is the clinic closed?','Monday','Tuesday','every Friday','告示说诊所星期一休息。'),q('When did the patient book instead?','Tuesday','Monday','the previous Saturday','病人改约星期二。'),q('Which spelling is correct for the weekday?','Monday','monday','Mondayss','星期名 Monday 首字母大写。',1,'capitalization'),q('The older English name mōnandæg referred to?','the day of the moon','a day for melting metal','the first day of every workweek worldwide','该词源字面为 moon’s day。',1,'word-formation')]);
P('monetary','Monetary comes from Latin monetarius, “of money,” from moneta, “mint or money”; it relates to a country’s currency or to money as wealth.',[C('monetary.s1','货币政策','The central bank announced a monetary policy change to keep inflation near its target.','中央银行宣布调整货币政策，以使通胀接近目标水平。','The central bank announced a monetary policy change / to keep inflation / near its target.','monetary 可修饰 policy，表示涉及货币供应、利率或汇率的政策。','中央银行通过货币政策管理通胀。','经济'),C('monetary.s2','金钱奖励','The award carried no monetary reward, but the winning team received public recognition for its design.','该奖项没有金钱奖励，但获胜团队因其设计获得了公开表彰。','The award carried no monetary reward / but the winning team received public recognition / for its design.','monetary reward 指以钱款形式给予的奖励。','此处 monetary 表示奖金，而非货币政策。','经济')],M('The prize offered a monetary reward, but the organisers confirmed that no money would be paid.','The prize offered no monetary reward, only public recognition.','没有付款就没有 monetary reward。','word-choice'),[q('What did the central bank change?','monetary policy','the monastery’s library hours','the weekday calendar','央行调整的是货币政策。',1),q('What kind of reward did the design award lack?','a money payment','a public announcement','a new constitution','奖项没有金钱奖励。',2),q('Which issue is monetary?','a central bank interest-rate decision','a monastery’s visitor schedule','a monarch’s opening speech','利率属于货币政策范畴。',1,'context'),q('Monetary is related to?','currency or money','mollusks','monasteries only','monetary 表示货币或金钱相关。',1,'meaning')]);
P('money','Money came through Old French moneie from Latin moneta, the mint and coined money; it can mean currency or funds and wealth.',[C('money.s1','日常货币','The cashier returned the correct amount of money after the customer paid for the groceries in cash.','顾客用现金买完杂货后，收银员找回了正确金额的钱。','The cashier returned the correct amount of money / after the customer paid / for the groceries in cash.','money 可指支付商品的硬币、纸币或银行账户金额。','顾客付款并获得找零，体现日常货币义。','金融'),C('money.s2','可用资金','The hospital raised enough money for a new scanner, although the equipment would not arrive until autumn.','医院筹集到足够资金购买新扫描仪，尽管设备要到秋天才会到货。','The hospital raised enough money / for a new scanner / although the equipment would not arrive / until autumn.','money 也可指为某个用途筹集或持有的资金。','这里是为采购设备筹集的财力。','金融')],M('The hospital had enough money for the scanner, but its budget contained no funds at all.','The hospital raised enough money in its budget to pay for the scanner.','若预算中完全没有资金，就不能说筹到了足够的钱。','meaning'),[q('What did the cashier return?','the correct amount of currency','a new scanner','the customer’s groceries','cashier 找回正确金额的钱。',1),q('What did the hospital raise money for?','a new scanner','a new monastery','a monarch’s speech','医院筹资购买扫描仪。',2),q('In “money for a new scanner,” money means?','funds available for a purpose','coins only, never a budget','an exact moment','此处 money 指采购设备的资金。',2,'meaning'),q('Which phrase treats money as wealth or funds?','The project ran out of money.','She placed a coin in the machine.','He counted one note.','项目缺少 funds，体现资金义。',2,'context')]);
P('mongrel','Mongrel was formed from obsolete mong (“mixture”), related to Old English gemong (“mingling”), plus the pejorative suffix -rel; it first referred to mixed-breed dogs.',C('mongrel.s1','混种犬','The shelter described Pip as a mongrel because his coat and build showed features of several dog breeds.','收容所把皮普称为杂种狗，因为它的毛色和体格呈现出几种犬种的特征。','The shelter described Pip as a mongrel / because his coat and build / showed features of several dog breeds.','mongrel 作名词指混有不同犬种血统的狗；也可作形容词表示混杂来源。','身体特征表明狗来自多个犬种。','动物'),M('The shelter called the purebred dog a mongrel even though its documented parents belonged to the same registered breed.','The shelter called the dog a mongrel because its ancestry included several breeds.','有可靠记录的同一纯种血统与“混种狗”不符。','meaning'),[q('Why was Pip described as a mongrel?','he showed features of several breeds','he had one documented purebred lineage','he lived in a monastery','狗呈现几种犬种特征。'),q('What does mongrel usually describe?','an animal of mixed breed or origin','an animal with a single verified breed','a person who monitors a process','mongrel 通常指混种动物。'),q('Which dog is a mongrel?','one whose ancestry includes several breeds','one with a documented single breed line','one trained to guide visitors','多犬种血统的狗符合 mongrel。',1,'context'),q('Why avoid casually using mongrel for a person?','the human application can be derogatory','it is a formal job title','it means a neutral day of the week','该词用于人可能带贬义，应用时应谨慎。',1,'register')]);
P('monitor','Monitor is from Latin monitor, “one who warns or advises,” from monere (“warn”); it names a display or supervisor and also means to watch a process over time.',[C('monitor.s1','电子显示器','The camera monitor showed a clear image of the loading bay while the guard watched from the control room.','摄像监视器清晰显示装货区的画面，保安则在控制室查看。','The camera monitor showed a clear image / of the loading bay / while the guard watched / from the control room.','monitor 作名词可指显示图像或信息的屏幕设备。','摄像画面出现在监视器屏幕上。','电子'),C('monitor.s2','监督人员','A trained monitor stayed beside the exam room to ensure that candidates followed the test rules.','一名受过培训的监考员守在考场旁，确保考生遵守考试规则。','A trained monitor stayed beside the exam room / to ensure / that candidates followed the test rules.','monitor 作名词也指负责观察并监督人或流程的人。','监考员监督考生遵守规则。','教育'),C('monitor.s3','持续监测','Nurses monitor the patient’s temperature every hour and call the doctor if it begins to rise.','护士每小时监测病人体温，若体温开始升高便通知医生。','Nurses monitor the patient’s temperature every hour / and call the doctor / if it begins to rise.','monitor 作及物动词表示持续观察、检查变化。','护士重复检查体温并根据变化采取行动。','医疗')],M('The nurses monitored the patient by refusing to check the temperature or observe any change.','The nurses monitored the patient by checking the temperature regularly.','不观察、不检查不能称为监测。','meaning'),[q('What appeared on the camera monitor?','an image of the loading bay','the patient’s temperature as a spoken warning','the candidates’ exam papers','屏幕显示装货区画面。',1),q('What did the trained monitor do?','watched candidates to ensure they followed rules','displayed a camera image','measured a monarch’s powers','监考员监督考生遵守规则。',2),q('What did the nurses monitor?','the patient’s temperature over time','the shape of a chocolate mould','a course’s monetary budget','护士持续监测病人体温。',3),q('Which sentence uses monitor as a verb?','The team monitored river levels each day.','The monitor displayed the map.','A monitor supervised the entrance.','monitored 在此表示持续监测水位。',3,'grammar')]);
P('monitoring','Monitoring is monitor plus -ing and names the continued observation of a person, process, or condition.',C('monitoring.s1','环境监测','Continuous monitoring of the river showed a rise in pollution after the factory restarted production.','对河流的持续监测显示，工厂恢复生产后污染有所上升。','Continuous monitoring of the river / showed a rise in pollution / after the factory restarted production.','monitoring 作不可数名词，表示一段时间内持续观察或测量。','数据对比呈现了污染变化。','环境'),M('The report called it continuous monitoring even though no one collected data or checked the river.','The report called it continuous monitoring because sensors recorded river conditions over time.','没有持续观察或数据记录就不能称为监测。'),[q('What did river monitoring reveal?','pollution rose after production restarted','the river became a monastery','a clinic closed on Monday','监测显示复产后污染上升。'),q('Monitoring means?','continued observation or measurement','a single unrecorded guess','an old religious building','monitoring 指持续观察或测量。'),q('Which is an example of environmental monitoring?','sensors recording air quality every hour','a one-time photograph with no follow-up','a dog showing mixed-breed features','连续记录空气质量属于环境监测。',1,'context'),q('Monitoring is formed from monitor plus?','-ing','-ous','-ship','monitor + -ing 构成名词 monitoring。',1,'word-formation')]);
P('monk','Monk came from Old English munuc, from Latin monachus and Greek monakhos, “solitary.”',C('monk.s1','宗教身份','The monk tended the monastery garden and spent part of each day in prayer with the other members of his community.','这名僧侣照料修道院花园，并每天与共同体其他成员一起祈祷一段时间。','The monk tended the monastery garden / and spent part of each day in prayer / with the other members of his community.','monk 作名词指生活在宗教共同体中的男性修士。','修道院生活和共同祈祷体现僧侣身份。','宗教'),M('The monk was a secular market trader with no membership in a religious community.','The monk lived as a member of a religious community.','普通市场商贩并非僧侣。','confusable'),[q('What did the monk tend?','the monastery garden','the parliament chamber','the camera monitor','僧侣照料修道院花园。'),q('With whom did he pray?','other members of his community','the elected ministers','the clinic’s patients','他与宗教共同体成员一同祈祷。'),q('A monk is a man who?','lives in a religious community','rules a country as a monarch','supervises an exam for payment','monk 指宗教共同体中的男性修士。',1,'meaning'),q('The Greek source monakhos is associated with?','being solitary','melting glass','having mixed ancestry','monakhos 与独居、修行的意思相关。',1,'word-formation')]);
P('monkey','Monkey entered English in the 16th century, perhaps through Middle Low German or Middle Dutch, but its exact origin is uncertain.',[C('monkey.s1','动物名称','The young monkey climbed the rope, paused on a branch, and reached for the fruit held by its keeper.','小猴子爬上绳子，在树枝上停了一会儿，然后伸手去拿饲养员手中的水果。','The young monkey climbed the rope / paused on a branch / and reached for the fruit / held by its keeper.','monkey 作名词指会攀爬的灵长类动物；与无尾猿的动物分类有别。','动物攀爬并伸手取果，体现名词义。','动物'),C('monkey.s2','淘气孩子','The teacher smiled when the little monkey returned the missing chalk and admitted hiding it as a joke.','那个淘气的小家伙把藏起来的粉笔还给老师，并承认只是开玩笑，老师笑了。','The teacher smiled / when the little monkey returned the missing chalk / and admitted hiding it / as a joke.','口语中 monkey 可亲昵或责备地称淘气的孩子。','孩子恶作剧后归还粉笔，体现口语比喻义。','口语'),C('monkey.s3','乱摆弄','Do not monkey with the laboratory controls; the calibration is delicate and changing one setting could ruin the experiment.','不要乱动实验室控制装置；校准很精细，改动一个设置就可能毁掉实验。','Do not monkey with the laboratory controls / the calibration is delicate / and changing one setting / could ruin the experiment.','monkey with something 是口语短语，意为随意摆弄或擅自改动。','不要擅自改动精密控制装置。','口语')],M('The technician monkeyed with the controls by leaving every setting untouched and making no adjustment.','The technician monkeyed with the controls by changing settings without authorisation.','不触碰或改动设置不符合 monkey with 的意思。','collocation'),[q('What did the young monkey reach for?','fruit held by its keeper','a chemistry textbook','the exam schedule','例句中的动物伸手取水果。',1),q('Why did the teacher call the child a little monkey?','the child had hidden chalk as a joke','the child was a primate','the child monitored river pollution','口语比喻指淘气的孩子。',2,'register'),q('What does monkey with the controls mean?','change or handle them carelessly','watch them without touching','use them to calculate momentum','monkey with 表示乱摆弄。',3,'collocation'),q('Which sentence uses monkey as an animal?','A monkey climbed the branch for fruit.','Don’t monkey with the settings.','The little monkey hid the chalk.','爬树取果的主语是动物 monkey。',1,'context')]);
P('monochromatic','Monochromatic combines Greek mono-, “one,” with chromatic, from chrōma (“colour”); it describes one hue or a single wavelength of light.',C('monochromatic.s1','单色影像','The photographer chose a monochromatic palette of blue shades, keeping the portrait calm and visually unified.','摄影师选择了由不同蓝色构成的单色调，让肖像显得平静而统一。','The photographer chose a monochromatic palette / of blue shades / keeping the portrait calm / and visually unified.','monochromatic 作形容词可表示只用一种色调，也可指单一波长的光。','画面用同一蓝色色相的深浅变化。','艺术'),M('The designer called the poster monochromatic even though it used unrelated red, green, and yellow hues equally.','The designer used several shades of one blue hue for a monochromatic poster.','多种不同色相平等并用不是单色调。','meaning'),[q('Which palette did the photographer choose?','different shades of blue','equal amounts of red, green, and yellow','only black text on a clear screen','不同深浅的蓝色构成单色色调。'),q('What effect did the palette create?','a calm and unified portrait','a brighter sound signal','a larger monastery','例句说单色调让肖像更平静统一。'),q('A monochromatic image uses?','one hue, often in several shades','every colour in equal amounts','no colours and no light','monochromatic 指单一色调。',1,'meaning'),q('The prefix mono- contributes the meaning?','one','many','movement','mono- 表示一个、单一。',1,'word-formation')]);
})();

(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('monochrome','Monochrome came from Greek monokhromos, “of a single colour,” combining monos (“single”) and khrōma (“colour”).',[C('monochrome.s1','摄影艺术','The archive displayed a monochrome photograph of the harbour, printed in black and white rather than in colour.','档案馆展出了一张港口黑白照片，以单色而非彩色印制。','The archive displayed a monochrome photograph / of the harbour / printed in black and white / rather than in colour.','monochrome 作名词指单色作品，常特指黑白图像。','照片仅以黑、白和灰阶呈现。','艺术'),C('monochrome.s2','单色画面','The film remains monochrome throughout, with no coloured scenes or tinted frames.','这部影片始终是单色画面，没有彩色场景或染色画格。','The film remains monochrome throughout / with no coloured scenes / or tinted frames.','monochrome 作形容词可修饰影片或图像，表示没有色彩变化或仅有黑白灰。','整部影片都采用单色画面。','艺术')],M('The gallery labelled its bright red-and-green photograph a monochrome because it contained several contrasting hues.','The gallery labelled its black-and-white photograph a monochrome.','红绿多色照片不符合单色作品的含义。','meaning'),[q('How was the harbour photograph printed?','in black and white','in bright red and green','as a moving film','黑白照片是 monochrome 作品。',1),q('What does monochrome describe in the film sentence?','the film has no coloured scenes','the film changes colour every second','the film contains no images','影片全程使用单色画面。',2),q('A monochrome is often?','an image made with one colour or black and white','a picture using many unrelated hues','a written speech by one actor','monochrome 名词可指单色或黑白图像。',1,'meaning'),q('Which sentence uses monochrome as an adjective?','The monochrome screen showed only grey tones.','She bought a monochrome for the gallery.','They monitored the monochrome.','修饰 screen 的 monochrome 是形容词。',2,'grammar')]);
P('monoculture','Monoculture combines mono- (“single”) with culture; the agricultural term entered English via French for cultivating one crop across a large area.',C('monoculture.s1','农业种植','The valley’s monoculture of maize left fields with little crop diversity and made harvests vulnerable to one pest.','山谷里单一种植玉米，田间作物缺乏多样性，也使收成容易受到一种害虫威胁。','The valley’s monoculture of maize / left fields with little crop diversity / and made harvests vulnerable / to one pest.','monoculture 作名词指大面积长期只种一种作物的农业方式。','单一种植降低多样性，并增加病虫害风险。','农业'),M('The farm practised monoculture by rotating many unrelated crops across every field each season.','The farm practised monoculture by planting the same crop across its fields year after year.','每季轮种多种作物不是单一种植。'),[q('Which crop dominated the valley?','maize','mussels','monks’ gardens','例句表明山谷主要只种玉米。'),q('What risk did monoculture create?','harvests could be vulnerable to one pest','the fields contained too many different crops','the crop changed its name','作物单一让害虫更容易造成大范围损失。'),q('Monoculture in farming means?','growing the same crop over a wide area repeatedly','growing several crops in rotation','keeping one plant inside a laboratory only','该词指大面积、长期单一种植。',1,'meaning'),q('Which practice is monoculture?','planting maize across the same fields year after year','changing crops among plots every season','combining several native crops in one field','同一作物年复一年占据大面积农田。',1,'context')]);
P('monogamous','Monogamous combines Greek mono- (“one”) and gamos (“marriage”); it describes pairing or marriage with one partner.',C('monogamous.s1','婚配关系','The study describes the swans as monogamous because the observed pair remained together through several breeding seasons.','研究把天鹅描述为单配的，因为观察到的这对天鹅在多个繁殖季节里始终在一起。','The study describes the swans as monogamous / because the observed pair remained together / through several breeding seasons.','monogamous 作形容词描述与一个伴侣配对或婚配的关系。','研究记录的是一对伴侣持续多个繁殖季节。','生物'),M('The report called the animal monogamous while documenting that it regularly paired with several partners at the same time.','The report called the animal monogamous because it paired with one partner.','同时与多个伴侣配对与 monogamous 的定义相反。'),[q('Why did the study call the swans monogamous?','the pair stayed together across breeding seasons','each bird changed partners every day','the birds lived without any pair bond','研究记录这对天鹅持续配对。'),q('Monogamous describes pairing with?','one partner','several partners at once','no other animal or person','mono- 表示单一伴侣。'),q('Which relationship is monogamous?','a pair that has one partner each','one person simultaneously marrying several partners','a group with no pair relationship','单一配偶关系符合该形容词。',1,'context'),q('Monogamous is the adjective; the related noun is?','monogamy','monograph','monotony','monogamy 是表示单配制度或关系的名词。',1,'word-formation')]);
P('monogamy','Monogamy comes from Greek monos (“one”) and gamos (“marriage”); it names marriage or mating with one partner.',C('monogamy.s1','婚姻制度','The article compares monogamy with other marriage systems without claiming that every culture follows the same custom.','文章比较单偶婚姻与其他婚姻制度，并未声称所有文化都遵循同一种习俗。','The article compares monogamy with other marriage systems / without claiming / that every culture follows the same custom.','monogamy 作名词指与单一伴侣结婚或配对的制度、关系。','文章把单偶婚姻作为一种制度加以比较。','社会'),M('The report defined monogamy as a marriage system in which each person has several spouses at the same time.','The report defined monogamy as marriage to one partner at a time.','同时拥有多位配偶与 monogamy 的单一伴侣定义相反。'),[q('What does the article compare with other marriage systems?','monogamy','monochrome photography','a monarchy','文章比较的是单偶婚姻制度。'),q('Monogamy concerns marriage or mating with?','a single partner','several simultaneous spouses','no partner under any circumstances','monogamy 的核心是单一伴侣。'),q('Which topic is about monogamy?','a society’s rule of one spouse at a time','a crop grown over a wide tract','a film made in black and white','单配婚姻制度属于 monogamy。',1,'context'),q('Monogamy is a?','noun for a relationship or system','verb meaning to dominate a market','plural adjective for colours','monogamy 是名词。',1,'grammar')]);
P('monograph','Monograph combines Greek mono- (“single”) and -graph (“something written”); it is a scholarly work on one subject and can also mean to write such a work.',[C('monograph.s1','学术专著','Her monograph examines one narrow question in medieval trade, drawing on shipping records from three coastal towns.','她的专题论著研究中世纪贸易中的一个具体问题，并参考了三个沿海城镇的航运记录。','Her monograph examines one narrow question / in medieval trade / drawing on shipping records / from three coastal towns.','monograph 作名词指集中研究单一主题的学术书或长篇论文。','全书聚焦一个狭窄的研究问题。','学术'),C('monograph.s2','撰写专著','After finishing the fieldwork, the historian monographed the monastery’s records in a study of regional land ownership.','完成实地调查后，历史学家撰写了一部关于修道院档案的专著，研究当地土地所有权。','After finishing the fieldwork / the historian monographed the monastery’s records / in a study / of regional land ownership.','monograph 也可作及物动词，表示撰写关于某一主题的专著。','动词后接 records，表示以这些档案为主题撰写研究。','学术')],M('The historian monographed the records by writing a broad survey that covered unrelated topics without studying them.','The historian monographed the records by writing a focused study of them.','monograph 动词强调围绕特定主题作集中研究，不是泛泛概述。','word-choice'),[q('What subject does the scholar’s monograph examine?','one focused question in medieval trade','every topic in modern biology','a single colour in a photograph','专著研究一个具体的贸易问题。',1),q('What did the historian do after fieldwork?','wrote a focused study of the monastery records','discarded all the records','opened a market monopoly','monographed 在此作动词，指写专著研究档案。',2),q('A monograph is usually?','a scholarly work focused on one subject','a collection of unrelated short jokes','a display screen','monograph 名词指专题学术作品。',1,'meaning'),q('The prefix mono- in monograph means?','one or single','many','stone','mono- 表示单一主题。',1,'word-formation')]);
P('monolithic','Monolithic comes from monolith plus -ic; literally it means made of one stone and figuratively describes something massive and undifferentiated.',C('monolithic.s1','整体划一','The review criticised the agency’s monolithic structure, where every regional office had to follow identical procedures.','评论批评该机构整体划一的结构，因为所有地区办事处都必须遵循完全相同的程序。','The review criticised the agency’s monolithic structure / where every regional office / had to follow / identical procedures.','monolithic 可比喻庞大且缺乏内部差异或灵活性的组织。','各地区办事处都被要求采用完全相同的程序。','组织'),M('The review called the agency monolithic because each regional office operated independently with very different procedures.','The review called the agency monolithic because every regional office followed the same rigid procedures.','地区机构高度独立且做法各异，不符合“整体划一”的比喻义。'),[q('What feature of the agency was criticised?','its rigid, uniform structure','its many independent local policies','its black-and-white photographs','各办公室必须遵循相同程序。'),q('Monolithic can literally describe something?','made from one large block of stone','made from many loose grains','that changes every hour','monolithic 的字面义与独块巨石有关。',1,'meaning'),q('Which organisation seems monolithic?','one where all branches must follow the same rigid rules','one where each branch sets unrelated policies','one with no central structure','统一而庞大的结构符合比喻义。',1,'context'),q('In “a monolithic agency,” monolithic is a/an?','adjective modifying agency','noun naming a book','verb meaning write a study','monolithic 修饰名词 agency。',1,'grammar')]);
P('monologue','Monologue came through French from Late Greek monologos, “speaking alone,” from monos (“single”) and logos (“speech”).',C('monologue.s1','戏剧独白','In the final monologue, the actor remained alone on stage and explained why the character had hidden the letter.','在最后一段独白中，演员独自留在舞台上，解释角色为何藏起那封信。','In the final monologue / the actor remained alone on stage / and explained / why the character had hidden the letter.','monologue 作名词指一个人持续较长时间的讲话或戏剧独白。','舞台上由一名角色单独讲话。','戏剧'),M('The scene was a monologue in which four characters exchanged short lines with one another.','The scene was a monologue in which one character spoke alone at length.','多名角色轮流对话不是一个人的独白。','confusable'),[q('Where was the actor during the final monologue?','alone on stage','in the audience','in the monastery library','演员独自在台上讲话。'),q('What did the actor explain?','why the character had hidden the letter','how the camera monitor worked','why a crop had failed','独白解释了角色藏信的原因。'),q('A monologue is a speech by?','one person speaking alone for some time','several people trading short replies','a choir singing together','monologue 指一人持续讲话。',1,'meaning'),q('Which scene is a monologue?','one character speaks alone about a decision','two people debate in short turns','a narrator lists several speakers’ lines','独自长篇讲话符合 monologue。',1,'context')]);
P('monopolise','Monopolise is the British -ise spelling of monopolize, formed from monopoly plus -ise; it means to control a supply or dominate a conversation.',[C('monopolise.s1','占据谈话','At dinner, Nina monopolised the conversation by talking through every topic and leaving no space for others to reply.','晚餐时，妮娜一直占着话头，谈遍每个话题，不给别人回应的空隙。','At dinner / Nina monopolised the conversation / by talking through every topic / and leaving no space for others to reply.','monopolise 作及物动词可接 conversation，表示独占谈话、不让别人参与。','她持续发言，使其他人无法回应。','社交'),C('monopolise.s1','控制供应','One supplier monopolised the local salt trade, leaving shops with no alternative source for the product.','一家供应商垄断了当地食盐贸易，使商店没有其他货源。','One supplier monopolised the local salt trade / leaving shops / with no alternative source / for the product.','monopolise 也表示独占商品或服务的全部供应。','当地商店没有其他食盐来源。','经济')],M('Nina monopolised the conversation by inviting every guest to speak and carefully sharing the floor.','Nina monopolised the conversation by speaking continuously and preventing others from joining in.','主动让每位客人发言并分享话轮不是独占谈话。','collocation'),[q('What did Nina monopolise at dinner?','the conversation','the local salt trade','the monastery garden','她独占了谈话。',1),q('What happened to the local salt supply?','one supplier controlled the whole trade','many suppliers competed equally','the shops grew their own salt','一家供应商控制了当地食盐贸易。',1),q('Which spelling is accepted in British English?','monopolise','monopolizee','monoplyse','monopolise 是常见英式 -ise 拼法。',1,'spelling'),q('Which behaviour would monopolise a discussion?','speaking so much that others cannot contribute','asking quiet guests for their views','taking turns with other speakers','不让别人发言就是独占讨论。',1,'context')]);
P('monopolist','Monopolist is monopoly plus -ist; it names a person or company that controls the supply of a commodity or service.',C('monopolist.s1','市场供应者','The regulator questioned the monopolist after it bought its only local competitor and controlled nearly all water deliveries.','监管机构在该公司收购唯一的本地竞争对手、几乎控制全部供水后，对这家垄断者展开质询。','The regulator questioned the monopolist / after it bought its only local competitor / and controlled nearly all water deliveries.','monopolist 作可数名词指控制某类商品或服务供应的人或公司。','收购竞争者后，该企业几乎控制全部供水。','经济'),M('The regulator called the tiny seller a monopolist although dozens of equal suppliers controlled the water market.','The regulator called the company a monopolist after it controlled nearly all water deliveries.','供应分散在许多平等竞争者手中时，单一垄断者的说法不成立。'),[q('Why did the regulator question the company?','it controlled nearly all local water deliveries','it sold one bottle of water','it published a monochrome photograph','公司收购竞争者后控制了大部分供水。'),q('A monopolist is a person or company that?','controls the supply of a commodity or service','buys products from many equal sellers','monitors a river for pollution','monopolist 指控制商品或服务供应者。'),q('Which business is a monopolist?','the sole local provider of a service with market control','one of many equal shops selling the same product','a research team with several projects','单一供应商掌控市场可称垄断者。',1,'context'),q('Monopolist is formed from monopoly plus?','-ist','-less','-ous','-ist 可表示从事或具有相关身份的人。',1,'word-formation')]);
P('monopolistic','Monopolistic is formed from monopoly plus -istic and means relating to a market controlled by one seller or a small number of sellers.',C('monopolistic.s1','市场结构','The report found the regional internet market monopolistic because one provider could set prices without meaningful competition.','报告认定当地互联网市场具有垄断性，因为一家供应商能够在缺少实质竞争的情况下定价。','The report found the regional internet market monopolistic / because one provider could set prices / without meaningful competition.','monopolistic 作形容词，描述由一家或少数卖家控制的市场状况。','供应商可以缺乏竞争地定价，说明市场垄断性强。','经济'),M('The report called the market monopolistic even though hundreds of equal providers competed freely and none could control prices.','The report called the market monopolistic because one provider dominated and faced little competition.','大量平等竞争者且无人控制价格，不符合垄断市场特征。'),[q('Why was the internet market called monopolistic?','one provider could set prices with little competition','hundreds of equal providers set independent prices','customers had no need for internet','一家供应商主导并缺乏竞争。'),q('Monopolistic describes something?','related to market control by one or few sellers','made from a single stone only','related to a single colour','monopolistic 是与市场垄断相关的形容词。'),q('Which market is monopolistic?','one seller dominates and competitors have little influence','many sellers compete on equal terms','buyers produce their own goods','一家主导、缺少竞争的市场符合定义。',1,'context'),q('Monopolistic is formed from monopoly plus?','-istic','-ify','-ment','-istic 构成形容词 monopolistic。',1,'word-formation')]);
P('monopolize','Monopolize is monopoly plus -ize and means to obtain exclusive control of a trade, resource, or share of attention.',[C('monopolize.s1','独占资源','The developer tried to monopolize the spring by buying every parcel of land around the only public water source.','开发商试图独占这处泉水，买下了唯一公共水源周围的所有地块。','The developer tried to monopolize the spring / by buying every parcel of land / around the only public water source.','monopolize 作及物动词表示取得排他性控制或占据全部资源。','买下水源周边土地意在独占泉水。','经济'),C('monopolize.s1','占满注意','During the workshop, one participant monopolized the discussion and left little time for questions.','研讨会上，一名参与者占满了讨论时间，几乎没给提问留时间。','During the workshop / one participant monopolized the discussion / and left little time / for questions.','monopolize 可比喻独占谈话、时间或注意力。','参与者占用大部分讨论时间。','社交')],M('One participant monopolized the workshop discussion by speaking for only a moment and giving everyone else most of the time.','One participant monopolized the workshop discussion by taking most of the speaking time.','只说片刻且给别人留出大部分时间不是独占讨论。','meaning'),[q('What did the developer try to monopolize?','the spring and its surrounding land','the monastery’s library','the whole rainy season','开发商意图独占公共泉水周围的土地。',1),q('How did one participant affect the workshop?','they took most of the discussion time','they left the meeting before it began','they supplied internet service','参与者占用了大部分讨论时间。',1),q('Monopolize can mean to?','gain exclusive control or take nearly all of something','share something equally','observe something over time','monopolize 表示独占或占去大部分。',1,'meaning'),q('Which is an example of monopolizing attention?','one speaker prevents anyone else from joining the discussion','a moderator invites each person to contribute','a group divides speaking time evenly','阻止他人参与就是独占注意力。',1,'context')]);
P('monopoly','Monopoly came from Greek monopōlion, “exclusive sale,” combining monos (“single”) and pōlein (“to sell”); it means exclusive market control or sole possession.',[C('monopoly.s1','市场垄断','The company held a monopoly on ferry services to the island, so regulators required it to publish its fares.','这家公司垄断了通往该岛的渡轮服务，因此监管机构要求其公布票价。','The company held a monopoly on ferry services / to the island / so regulators required it / to publish its fares.','monopoly 作名词指对某种商品或服务贸易的独占控制。','岛上渡轮只有一家运营商。','经济'),C('monopoly.s2','独占权力','The chair had no monopoly on good ideas; junior staff were encouraged to challenge her proposals.','主席并不独占好点子；初级员工也被鼓励质疑她的提案。','The chair had no monopoly on good ideas / junior staff were encouraged / to challenge her proposals.','monopoly 也可比喻某人或某群体独占某物或某种能力。','主席并非唯一能提出好想法的人。','社交')],M('The ferry company had a monopoly, but several rival operators provided the same route under equal conditions.','The ferry company had a monopoly because it was the only operator on the route.','有多个平等竞争的运营商就不构成该航线的独占。'),[q('Why did regulators require the ferry company to publish fares?','it was the sole operator on the route','it had no control over ferry services','it ran a monastery library','公司独占该岛渡轮服务。',1),q('What does “no monopoly on good ideas” mean?','the chair is not the only person who can have them','the chair sells ideas as a product','junior staff may not offer ideas','短语表示好点子并非主席独有。',2),q('A monopoly in a market usually means?','one seller exclusively controls a product or service','many equal sellers compete freely','customers own the suppliers','monopoly 市场义指独占商品或服务供应。',1,'meaning'),q('Which statement uses monopoly figuratively?','No one has a monopoly on kindness.','The firm controls all ferry tickets.','The island has one ferry route.','此处 monopoly 比喻独占某种品质。',2,'context')]);
P('monotheism','Monotheism combines Greek mono- (“one”) and theos (“god”); it is a religious system centred on one deity.',C('monotheism.s1','宗教观念','The course compares monotheism with polytheism, explaining how beliefs about the number of deities differ.','课程把一神论与多神论进行比较，解释两者对神祇数量的信仰差异。','The course compares monotheism with polytheism / explaining how beliefs differ / about the number of deities.','monotheism 作名词指以一位神为中心的宗教信仰或体系。','课程比较一神与多神的信仰观念。','宗教'),M('The textbook defined monotheism as worship of many unrelated gods at the same time.','The textbook defined monotheism as belief in one deity.','信仰多位神祇是多神论，不是一神论。','confusable'),[q('What does the course compare?','belief in one deity with belief in many deities','two kinds of monochrome photography','two crop-rotation calendars','课程比较一神论与多神论。'),q('Monotheism is centred on?','a single deity','many unrelated deities','no religious belief of any kind','mono- means one, and the system centres on one deity。'),q('Which belief system is monotheistic?','one centred on a single god','one centred on several gods','one concerned only with market prices','一位神祇是 monotheism 的核心。',1,'context'),q('Theos in monotheism means?','god or deity','stone','speech','希腊词 theos 意为神。',1,'word-formation')]);
P('monotonous','Monotonous comes from Greek monotonos, “in one tone,” from monos (“one”) and tonos (“tone”); it describes dull sameness.',C('monotonous.s1','乏味工作','The long safety recording became monotonous because the speaker repeated the same warning in an unchanging voice.','冗长的安全录音变得单调乏味，因为说话者用毫无变化的语调重复同一警告。','The long safety recording became monotonous / because the speaker repeated the same warning / in an unchanging voice.','monotonous 作形容词描述因反复相同或缺少变化而令人厌倦。','重复内容加上不变语调造成乏味。','声音'),M('The recording sounded monotonous because every sentence used a lively new voice and a different rhythm.','The recording sounded monotonous because its voice and rhythm never changed.','声音和节奏不断变化，不符合单调重复的描述。'),[q('Why did the safety recording become monotonous?','it repeated one warning in an unchanging voice','it used a new speaker for every line','it ended after one short sentence','内容和语调缺少变化。'),q('Monotonous usually describes something?','dull because it stays the same','exciting because it constantly changes','important enough to alter history','monotonous 指因单一重复而乏味。'),q('Which task sounds monotonous?','copying the same figures for hours without variation','performing a different song every minute','solving a new puzzle each day','长时间重复同一任务显得单调。',1,'context'),q('Monotonous is related to the idea of?','one repeated tone','many separate partners','a single oxygen atom','其希腊构词含“一个音调”之意。',1,'word-formation')]);
P('monotony','Monotony came from Greek monotonia, “sameness of tone,” based on monos (“one”) and tonos (“tone”).',C('monotony.s1','日常单调','To break the monotony of the night shift, the nurses took turns sharing a new puzzle during their break.','为了打破夜班生活的单调，护士们轮流在休息时分享新谜题。','To break the monotony of the night shift / the nurses took turns / sharing a new puzzle / during their break.','monotony 作不可数名词指持续不变、令人乏味的状态。','新谜题为重复的夜班带来变化。','生活'),M('The varied night shift broke its monotony by repeating precisely the same task and conversation every hour.','The nurses broke the monotony by adding a new puzzle to their break.','不断重复相同活动会加重单调，不会打破它。'),[q('What helped break the night-shift monotony?','sharing a new puzzle','repeating the same task every hour','closing the hospital permanently','新谜题给夜班带来变化。'),q('Monotony means?','a dull sameness that continues','a brief moment of silence','control of a whole market','monotony 指持续的乏味重复。'),q('Which situation shows monotony?','each day follows the same dull routine','each day brings a different route and task','a single dramatic event changes a city','每天都重复乏味例行安排。',1,'context'),q('Which word is the adjective related to monotony?','monotonous','monolithic','monograph','monotonous 是“单调的”形容词。',1,'word-formation')]);
P('monoxide','Monoxide combines mono- (“one”) with oxide; in chemistry it refers to an oxide containing one oxygen atom per molecule, such as carbon monoxide.',C('monoxide.s1','化学命名','Carbon monoxide is a colourless gas with one oxygen atom in each molecule, so a faulty heater can create a dangerous exposure.','一氧化碳是无色气体，每个分子含一个氧原子，因此故障取暖器可能造成危险暴露。','Carbon monoxide is a colourless gas / with one oxygen atom in each molecule / so a faulty heater / can create a dangerous exposure.','monoxide 指每个分子中含一个氧原子的氧化物；CO 是一氧化碳的化学式。','每个 CO 分子含一个氧原子。','化学'),M('The label called CO a monoxide even though each molecule contained three oxygen atoms.','The label called CO a monoxide because each molecule contains one oxygen atom.','monoxide 中的 mono- 表示一个氧原子。','measurement'),[q('How many oxygen atoms are in each carbon monoxide molecule?','one','two','three','CO 每个分子含一个氧原子。'),q('What danger is mentioned?','a faulty heater could expose people to the gas','the gas changes the day of the week','the gas is a type of crop','故障取暖器可能造成一氧化碳暴露。'),q('Which formula is carbon monoxide?','CO','CO₂','O₃','一氧化碳的化学式为 CO。',1,'context'),q('The prefix mono- in monoxide means?','one','two','without','mono- 表示一个。',1,'word-formation')]);
P('monsoon','Monsoon came through Dutch and Portuguese from Arabic mawsim, “season”; it names a seasonal wind and the rainy season that wind brings.',[C('monsoon.s1','季节风','The southwest monsoon shifted the coastal wind direction, bringing humid air toward the region each summer.','西南季风改变了沿海风向，每年夏季把潮湿空气带到该地区。','The southwest monsoon shifted the coastal wind direction / bringing humid air / toward the region / each summer.','monsoon 作名词可指造成季节性天气变化的季风。','例句侧重季节性风向改变。','气象'),C('monsoon.s2','季风雨季','Farmers prepared the rice fields before the monsoon began, expecting weeks of seasonal rain.','农民在季风雨季开始前整备稻田，预计会迎来数周的季节性降雨。','Farmers prepared the rice fields / before the monsoon began / expecting weeks / of seasonal rain.','monsoon 也可指由季风带来的雨季。','例句中指预期数周降雨的季节。','气象')],M('The farmers called it the monsoon season even though no seasonal winds or rains arrived that year.','The farmers prepared for the monsoon season because seasonal winds and rains were expected.','没有季风或季节性降雨时，不能据此称为该季风雨季。'),[q('What changed the coastal wind direction?','the southwest monsoon','a monastery bell','the harvest schedule','西南季风改变了风向。',1),q('What did farmers expect during the monsoon?','weeks of seasonal rain','a single winter snowflake','a change in the monarchy','农民预计雨季会持续数周。',2),q('Monsoon can mean?','a seasonal wind','the rainy season caused by that wind','both the wind and the rainy season','该词可指季风及其带来的雨季。',1,'meaning'),q('Which sentence uses monsoon for the rainy season?','The rice fields flooded during the monsoon.','The monsoon changed the wind direction.','The screen showed the wind monitor.','此处 monsoon 指季风雨季。',2,'context')]);
P('monster','Monster came through Old French from Latin monstrum, “portent or sign”; it now means a frightening creature, a cruel person, or something exceptionally large.',[C('monster.s1','虚构怪物','In the children’s story, a friendly monster guarded the bridge and asked travellers to solve a riddle before crossing.','儿童故事里，一只友善的怪物守着桥，并要求旅客答对谜语才能通过。','In the children’s story / a friendly monster guarded the bridge / and asked travellers / to solve a riddle before crossing.','monster 作名词常指令人害怕的虚构生物，也可用于童话角色。','故事中的怪物是桥的守护者。','文学'),C('monster.s2','残酷恶人','The memoir calls the torturer a monster because he deliberately inflicted suffering on prisoners.','回忆录称那名施刑者为恶魔，因为他故意让囚犯承受痛苦。','The memoir calls the torturer a monster / because he deliberately inflicted suffering / on prisoners.','monster 可比喻残忍恶毒的人，带强烈谴责语气。','故意折磨囚犯体现残酷恶人义。','评价'),C('monster.s3','巨大事物','The repair crew used a crane to move the monster of a generator out of the flooded basement.','维修人员用起重机把那台庞然大物般的发电机从被淹地下室移出。','The repair crew used a crane / to move the monster of a generator / out of the flooded basement.','口语中 monster 可指异常巨大、难以搬动的东西。','发电机大到需要起重机移动。','口语')],M('The memoir called the torturer a monster while describing him as consistently kind and unwilling to harm anyone.','The memoir called the torturer a monster because he deliberately harmed prisoners.','始终善良且不伤害他人的人不符合此处的“残酷恶人”义。','word-choice'),[q('Who guarded the bridge in the story?','a friendly monster','a market monopolist','a clinic nurse','故事中的怪物守桥并出谜题。',1),q('Why did the memoir call the torturer a monster?','he deliberately inflicted suffering','he repaired a generator','he guarded a bridge kindly','残酷施刑者符合比喻义。',2),q('What did the repair crew move with a crane?','an unusually large generator','a small hand tool','a brief moment','monster 可口语指庞然大物。',3,'meaning'),q('Which sentence uses monster for a cruel person?','The prisoners feared the guard who abused them; they called him a monster.','The monster in the tale guarded a bridge kindly.','A monster of a machine filled the basement.','虐待他人的看守体现恶人义。',2,'context')]);
P('monstrous','Monstrous is monster plus -ous and describes something like a monster in cruelty or extraordinary size.',C('monstrous.s1','骇人规模','The council rejected a monstrous tower design that would have blocked sunlight from every home on the narrow street.','市议会否决了一项庞大的塔楼设计，因为它会遮挡这条狭窄街道上所有住宅的阳光。','The council rejected a monstrous tower design / that would have blocked sunlight / from every home / on the narrow street.','monstrous 可表示规模巨大，也可形容行为残酷可怕。','塔楼大到会遮挡整条街的阳光。','建筑'),M('The council described the tiny garden shed as monstrous in size even though it could fit inside a cupboard.','The council described the tower as monstrous because it would dominate the entire narrow street.','能放进橱柜的小棚屋不属于异常巨大的建筑。','meaning'),[q('Why did the council reject the tower design?','it would block sunlight from every home','it was too small to be seen','it changed the town’s currency','塔楼会遮挡整条街住宅的阳光。'),q('Monstrous can describe?','extraordinary size or terrible cruelty','a brief moment only','a single crop planted each year','该词可指庞大或残酷可怕。'),q('Which structure could be called monstrous in size?','a tower overshadowing an entire street','a small garden shed','a modest desk lamp','遮挡整条街的大塔属于庞大建筑。',1,'context'),q('Monstrous is formed from monster plus?','-ous','-ise','-er','-ous 构成形容词 monstrous。',1,'word-formation')]);
P('montage','Montage came from French montage, “a mounting or assembly,” from monter (“to mount”); it describes joined film scenes or a collage of pictures.',[C('montage.s1','电影剪辑','A training montage shows the athlete practising at dawn, recovering from an injury, and finally winning the race.','训练蒙太奇展示运动员清晨训练、伤后恢复，最终赢得比赛。','A training montage shows the athlete practising at dawn / recovering from an injury / and finally / winning the race.','montage 在电影中指把一系列短镜头剪接在一起以呈现过程或故事。','多个训练片段按时间推进剪接。','电影'),C('montage.s2','图片拼贴','The students made a photo montage from family portraits, ticket stubs, and postcards for the history display.','学生们用家庭肖像、票根和明信片制作了一幅照片拼贴，供历史展览使用。','The students made a photo montage / from family portraits / ticket stubs / and postcards for the history display.','montage 也可指把多张照片或图像组合成的拼贴画。','作品由多种图片材料拼合而成。','艺术')],M('The editor called a single uninterrupted shot showing one scene a training montage.','The editor called a sequence of brief training scenes cut together a montage.','只有一个未剪接的连续镜头不构成由多个片段组成的蒙太奇。','meaning'),[q('What does the training montage show?','practice, recovery, and the final race','only a still family portrait','a market’s monthly prices','影片剪接多个训练阶段。',1),q('What materials formed the students’ photo montage?','portraits, ticket stubs, and postcards','one uninterrupted film shot','a single monochrome word','拼贴由多种照片和纸品组合。',2),q('A film montage is usually?','a sequence of edited scenes or shots','one continuous unedited shot','a speech by one actor alone','montage 指剪接组合的一系列镜头。',1,'meaning'),q('Which is a photo montage?','a picture assembled from several images','a single unaltered photograph','a recording of an actor’s monologue','多张图片拼合而成的是照片拼贴。',2,'context')]);
})();

})();
